    { const char * tb_v2213 = "// Библиотека, которую Tachbit кладёт в начало каждой программы на C.\n"; *(const char * *)tb_grow(v_lines) = tb_v2213; }
    { const char * tb_v2214 = "// Это обычный C. Компилятор на Tachbit встраивает этот текст через runtime_text.tb,\n"; *(const char * *)tb_grow(v_lines) = tb_v2214; }
    { const char * tb_v2215 = "// который делает tools/embed_runtime.py. Поменял этот файл — запусти:\n"; *(const char * *)tb_grow(v_lines) = tb_v2215; }
    { const char * tb_v2216 = "//     python3 tools/embed_runtime.py\n"; *(const char * *)tb_grow(v_lines) = tb_v2216; }
    { const char * tb_v2217 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
    { const char * tb_v2218 = "// Библиотека ядра Омниума (tb bare): то, что у обычной программы даёт ОС и libc.\n"; *(const char * *)tb_grow(v_lines) = tb_v2218; }
    { const char * tb_v2219 = "// Загрузка (multiboot → 64 бита), своя маленькая libc, память и квоты клеток, прерывания,\n"; *(const char * *)tb_grow(v_lines) = tb_v2219; }
    { const char * tb_v2220 = "// задачи и планировщик, страницы памяти, несколько ядер процессора (ACPI, APIC).\n"; *(const char * *)tb_grow(v_lines) = tb_v2220; }
    { const char * tb_v2221 = "// Компилятор вставляет этот файл в compiler/runtime.h на место строки //@include (tools/embed_runtime.py).\n"; *(const char * *)tb_grow(v_lines) = tb_v2221; }
    { const char * tb_v2222 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2222; }
    { const char * tb_v2223 = "// ---------- режим без ОС (tb bare): своя маленькая библиотека вместо libc ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2223; }
    { const char * tb_v2224 = "// Программа сама себе ОС: загружается через multiboot (QEMU, GRUB), пишет на экран\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "// (текстовый режим VGA) и в последовательный порт COM1, память берёт из своего запаса.\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
    { const char * tb_v2226 = "// Есть прерывания, таймер, клавиатура, задачи (background) и страницы памяти; файлов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v2226; }
    { const char * tb_v2227 = "#include <stddef.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2227; }
    { const char * tb_v2228 = "#include <stdarg.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2228; }
    { const char * tb_v2229 = "#include <stdint.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2229; }
    { const char * tb_v2230 = "// «переменные потока» — настоящие: у каждой задачи свой блок, на него смотрит регистр FS\n"; *(const char * *)tb_grow(v_lines) = tb_v2230; }
    { const char * tb_v2231 = "// (так их не надо копировать при смене задачи, и на нескольких ядрах процессора у каждого свои)\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "#define _Thread_local __thread __attribute__((tls_model(\"local-exec\")))\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
    { const char * tb_v2233 = "#define EOF (-1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2233; }
    { const char * tb_v2234 = "typedef struct tb_file FILE;\n"; *(const char * *)tb_grow(v_lines) = tb_v2234; }
    { const char * tb_v2235 = "#define stdout ((FILE *)1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2235; }
    { const char * tb_v2236 = "#define stderr ((FILE *)2)\n"; *(const char * *)tb_grow(v_lines) = tb_v2236; }
    { const char * tb_v2237 = "typedef long pthread_t;   // 8 байт, как адрес: раскладка задачи та же, что в обычной программе\n"; *(const char * *)tb_grow(v_lines) = tb_v2237; }
    { const char * tb_v2238 = "typedef int pthread_mutex_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v2238; }
    { const char * tb_v2239 = "#define PTHREAD_MUTEX_INITIALIZER 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2239; }
    { const char * tb_v2240 = "#define pthread_mutex_lock(m) ((void)(m))\n"; *(const char * *)tb_grow(v_lines) = tb_v2240; }
    { const char * tb_v2241 = "#define pthread_mutex_unlock(m) ((void)(m))\n"; *(const char * *)tb_grow(v_lines) = tb_v2241; }
    { const char * tb_v2242 = "#define _SC_NPROCESSORS_ONLN 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2242; }
    { const char * tb_v2243 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2243; }
    { const char * tb_v2244 = "TB_INL void tb_outb(unsigned short port, unsigned char v) { __asm__ volatile(\"outb %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "TB_INL unsigned char tb_inb(unsigned short port) { unsigned char v; __asm__ volatile(\"inb %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
