    { const char * tb_v2247 = "TB_INL unsigned short tb_inw(unsigned short port) { unsigned short v; __asm__ volatile(\"inw %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2247; }
    { const char * tb_v2248 = "TB_INL void tb_outl(unsigned short port, unsigned int v) { __asm__ volatile(\"outl %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2248; }
    { const char * tb_v2249 = "TB_INL unsigned int tb_inl(unsigned short port) { unsigned int v; __asm__ volatile(\"inl %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2249; }
    { const char * tb_v2250 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v2250; }
    { const char * tb_v2251 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v2251; }
    { const char * tb_v2252 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2252; }
    { const char * tb_v2253 = "typedef struct tb_cpu_s {\n"; *(const char * *)tb_grow(v_lines) = tb_v2253; }
    { const char * tb_v2254 = "    struct tb_cpu_s *self;\n"; *(const char * *)tb_grow(v_lines) = tb_v2254; }
    { const char * tb_v2255 = "    int id, apic, run, slice, depth, prev;   // run: номер задачи (-1 — пустой ход); depth: вложенность «общего замка»; prev: задача, которую отпустить после смены стека\n"; *(const char * *)tb_grow(v_lines) = tb_v2255; }
    { const char * tb_v2256 = "    uint64_t *idle_frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v2256; }
    { const char * tb_v2257 = "    unsigned char irq_tls[512 + 16] __attribute__((aligned(16)));   // переменные потока для функций прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v2257; }
    { const char * tb_v2258 = "    unsigned char idle_stack[16384] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
    { const char * tb_v2259 = "    unsigned char df_stack[16384] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2259; }
    { const char * tb_v2260 = "} tb_cpu;\n"; *(const char * *)tb_grow(v_lines) = tb_v2260; }
    { const char * tb_v2261 = "TB_API tb_cpu tb_cpus[TB_NCPU];\n"; *(const char * *)tb_grow(v_lines) = tb_v2261; }
    { const char * tb_v2262 = "TB_API int tb_ncpu = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2262; }
    { const char * tb_v2263 = "TB_INL tb_cpu *tb_me(void) { tb_cpu *c; __asm__ volatile(\"movq %%gs:0, %0\" : \"=r\"(c)); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2263; }
    { const char * tb_v2264 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v2264; }
    { const char * tb_v2265 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v2265; }
    { const char * tb_v2266 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2266; }
    { const char * tb_v2267 = "TB_INL uint64_t tb_irq_save(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2267; }
    { const char * tb_v2268 = "    uint64_t f;\n"; *(const char * *)tb_grow(v_lines) = tb_v2268; }
    { const char * tb_v2269 = "    __asm__ volatile(\"pushfq\\npopq %0\\ncli\" : \"=r\"(f) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2269; }
    { const char * tb_v2270 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2270; }
    { const char * tb_v2271 = "    if (c->depth++ == 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v2271; }
    { const char * tb_v2272 = "        while (__atomic_exchange_n(&tb_bkl, 1, __ATOMIC_ACQUIRE)) __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v2272; }
    { const char * tb_v2273 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v2273; }
    { const char * tb_v2274 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2274; }
    { const char * tb_v2275 = "TB_INL void tb_irq_restore(uint64_t f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2275; }
    { const char * tb_v2276 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2276; }
    { const char * tb_v2277 = "    if (--c->depth == 0) __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2277; }
    { const char * tb_v2278 = "    __asm__ volatile(\"pushq %0\\npopfq\" : : \"r\"(f) : \"memory\", \"cc\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2278; }
    { const char * tb_v2279 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2279; }
    { const char * tb_v2280 = "// отдать общий замок целиком (задача уходит навсегда — падает или кончилась)\n"; *(const char * *)tb_grow(v_lines) = tb_v2280; }
    { const char * tb_v2281 = "TB_INL void tb_bkl_drop(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2281; }
    { const char * tb_v2282 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2282; }
    { const char * tb_v2283 = "    if (c->depth > 0) { c->depth = 0; __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2283; }
    { const char * tb_v2284 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2284; }
    { const char * tb_v2285 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2285; }
    { const char * tb_v2286 = "// экран 80×25: байт буквы и байт цвета; русские буквы рисуем своим шрифтом (см. tb_vga_font)\n"; *(const char * *)tb_grow(v_lines) = tb_v2286; }
