    { const char * tb_v2289 = "TB_API unsigned char tb_vcolor = 0x0A;   // светло-зелёный на чёрном\n"; *(const char * *)tb_grow(v_lines) = tb_v2289; }
    { const char * tb_v2290 = "TB_API void tb_vga_put(unsigned char ch) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2290; }
    { const char * tb_v2291 = "    if (ch == '\\n') { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2291; }
    { const char * tb_v2292 = "    else if (ch == '\\b') { if (tb_vcol > 0) tb_vcol--; tb_vga[tb_vrow * 80 + tb_vcol] = (unsigned short)(tb_vcolor << 8 | ' '); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2292; }
    { const char * tb_v2293 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2293; }
