    { const char * tb_v2295 = "        if (++tb_vcol == 80) { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2295; }
    { const char * tb_v2296 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2296; }
    { const char * tb_v2297 = "    if (tb_vrow == 25) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2297; }
    { const char * tb_v2298 = "        for (int i = 0; i < 24 * 80; i++) tb_vga[i] = tb_vga[i + 80];\n"; *(const char * *)tb_grow(v_lines) = tb_v2298; }
    { const char * tb_v2299 = "        for (int i = 24 * 80; i < 25 * 80; i++) tb_vga[i] = (unsigned short)(tb_vcolor << 8 | ' ');\n"; *(const char * *)tb_grow(v_lines) = tb_v2299; }
