    { const char * tb_v2372 = "TB_API void tb_vga_font(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2372; }
    { const char * tb_v2373 = "    tb_outw(0x3C4, 0x0402); tb_outw(0x3C4, 0x0704);   // пишем в слой шрифта\n"; *(const char * *)tb_grow(v_lines) = tb_v2373; }
    { const char * tb_v2374 = "    tb_outw(0x3CE, 0x0204); tb_outw(0x3CE, 0x0005); tb_outw(0x3CE, 0x0406);\n"; *(const char * *)tb_grow(v_lines) = tb_v2374; }
