    { const char * tb_v2377 = "        for (int y = 0; y < 16; y++) font[(128 + i) * 32 + y] = tb_cyr_font[i][y];\n"; *(const char * *)tb_grow(v_lines) = tb_v2377; }
    { const char * tb_v2378 = "    tb_outw(0x3C4, 0x0302); tb_outw(0x3C4, 0x0304);   // обратно в текстовый режим\n"; *(const char * *)tb_grow(v_lines) = tb_v2378; }
    { const char * tb_v2379 = "    tb_outw(0x3CE, 0x0004); tb_outw(0x3CE, 0x1005); tb_outw(0x3CE, 0x0E06);\n"; *(const char * *)tb_grow(v_lines) = tb_v2379; }
    { const char * tb_v2380 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2380; }
    { const char * tb_v2381 = "TB_API unsigned char tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2381; }
    { const char * tb_v2382 = "TB_API void tb_putc(char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2382; }
    { const char * tb_v2383 = "    unsigned char ch = (unsigned char)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2383; }
    { const char * tb_v2384 = "    while ((tb_inb(0x3F8 + 5) & 0x20) == 0) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v2384; }
    { const char * tb_v2385 = "    tb_outb(0x3F8, ch);   // в порт — как есть (UTF-8)\n"; *(const char * *)tb_grow(v_lines) = tb_v2385; }
    { const char * tb_v2386 = "    if (ch < 0x80) { tb_utf_lead = 0; tb_vga_put(ch); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2386; }
    { const char * tb_v2387 = "    if (ch >= 0xC0) { tb_utf_lead = ch; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2387; }
    { const char * tb_v2388 = "    // второй байт: А..я = U+0410..U+044F, Ё = U+0401, ё = U+0451\n"; *(const char * *)tb_grow(v_lines) = tb_v2388; }
    { const char * tb_v2389 = "    unsigned cp = ((unsigned)(tb_utf_lead & 0x1F) << 6) | (ch & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v2389; }
    { const char * tb_v2390 = "    if (tb_utf_lead == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2390; }
    { const char * tb_v2391 = "    tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2391; }
    { const char * tb_v2392 = "    if (cp >= 0x410 && cp <= 0x44F) tb_vga_put((unsigned char)(128 + cp - 0x410));\n"; *(const char * *)tb_grow(v_lines) = tb_v2392; }
    { const char * tb_v2393 = "    else if (cp == 0x401) tb_vga_put(128 + 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v2393; }
    { const char * tb_v2394 = "    else if (cp == 0x451) tb_vga_put(128 + 65);\n"; *(const char * *)tb_grow(v_lines) = tb_v2394; }
    { const char * tb_v2395 = "    else tb_vga_put('?');\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "// строка не рвётся: пока задача не дописала свою строку до '\\n', другие ждут (недолго —\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "// если задача так и не допишет, через ~20 мс пишут всё равно)\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "TB_API volatile long long tb_line_owner = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "TB_API long long tb_out_me(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
    { const char * tb_v2401 = "TB_API int fputs(const char *s, FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
    { const char * tb_v2402 = "    if (!*s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2402; }
    { const char * tb_v2403 = "    long long me = tb_out_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2403; }
    { const char * tb_v2404 = "    uint64_t fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v2404; }
    { const char * tb_v2405 = "    for (long spins = 0;; spins++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2405; }
    { const char * tb_v2406 = "        fl = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v2406; }
    { const char * tb_v2407 = "        long long o = tb_line_owner;\n"; *(const char * *)tb_grow(v_lines) = tb_v2407; }
    { const char * tb_v2408 = "        if (o == 0 || o == me || me < 0 || spins > 4000000) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v2408; }
    { const char * tb_v2409 = "        tb_irq_restore(fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v2409; }
    { const char * tb_v2410 = "        __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v2410; }
    { const char * tb_v2411 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2411; }
    { const char * tb_v2412 = "    unsigned char was = tb_vcolor;\n"; *(const char * *)tb_grow(v_lines) = tb_v2412; }
    { const char * tb_v2413 = "    if (f == stderr) tb_vcolor = 0x0C;   // ошибки — красным\n"; *(const char * *)tb_grow(v_lines) = tb_v2413; }
    { const char * tb_v2414 = "    char last = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2414; }
    { const char * tb_v2415 = "    while (*s) { last = *s; tb_putc(*s++); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2415; }
    { const char * tb_v2416 = "    tb_vcolor = was;\n"; *(const char * *)tb_grow(v_lines) = tb_v2416; }
    { const char * tb_v2417 = "    if (me >= 0) tb_line_owner = last == '\\n' ? 0 : me;\n"; *(const char * *)tb_grow(v_lines) = tb_v2417; }
    { const char * tb_v2418 = "    tb_irq_restore(fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v2418; }
    { const char * tb_v2419 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2419; }
    { const char * tb_v2420 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2420; }
