    { const char * tb_v2431 = "// память: запас 64 МБ. Куски по размерам 16, 32, 64, ... байт; отданный кусок\n"; *(const char * *)tb_grow(v_lines) = tb_v2431; }
    { const char * tb_v2432 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2432; }
    { const char * tb_v2433 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v2433; }
