    { const char * tb_v2437 = "// заголовок куска: размер (номер 4..31) + метка «это начало куска» — так по адресу видно,\n"; *(const char * *)tb_grow(v_lines) = tb_v2437; }
    { const char * tb_v2438 = "// наш ли это кусок (для передачи владения), и хозяин (клетка) рядом\n"; *(const char * *)tb_grow(v_lines) = tb_v2438; }
