    { const char * tb_v2998 = "// --- клавиатура: буквы копятся в очереди, read_key() берёт по одной ---\n"; *(const char * *)tb_grow(v_lines) = tb_v2998; }
    { const char * tb_v2999 = "TB_API const char tb_kmap[2][58] = {\n"; *(const char * *)tb_grow(v_lines) = tb_v2999; }
    { const char * tb_v3000 = "    {0, 27, '1', '2', '3', '4', '5', '6', '7', '8', '9', '0', '-', '=', '\\b', '\\t',\n"; *(const char * *)tb_grow(v_lines) = tb_v3000; }
    { const char * tb_v3001 = "     'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '[', ']', '\\n', 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v3001; }
    { const char * tb_v3002 = "     'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', ';', '\\'', '`', 0, '\\\\',\n"; *(const char * *)tb_grow(v_lines) = tb_v3002; }
    { const char * tb_v3003 = "     'z', 'x', 'c', 'v', 'b', 'n', 'm', ',', '.', '/', 0, '*', 0, ' '},\n"; *(const char * *)tb_grow(v_lines) = tb_v3003; }
    { const char * tb_v3004 = "    {0, 27, '!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '_', '+', '\\b', '\\t',\n"; *(const char * *)tb_grow(v_lines) = tb_v3004; }
    { const char * tb_v3005 = "     'Q', 'W', 'E', 'R', 'T', 'Y', 'U', 'I', 'O', 'P', '{', '}', '\\n', 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v3005; }
    { const char * tb_v3006 = "     'A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L', ':', '\"', '~', 0, '|',\n"; *(const char * *)tb_grow(v_lines) = tb_v3006; }
    { const char * tb_v3007 = "     'Z', 'X', 'C', 'V', 'B', 'N', 'M', '<', '>', '?', 0, '*', 0, ' '}};\n"; *(const char * *)tb_grow(v_lines) = tb_v3007; }
    { const char * tb_v3008 = "TB_API char tb_kq[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3008; }
