    { const char * tb_v3011 = "TB_API char tb_ktext[256][2];\n"; *(const char * *)tb_grow(v_lines) = tb_v3011; }
    { const char * tb_v3012 = "// окно открыто (window_open): клавиши идут и сюда — для key_down и typed_text\n"; *(const char * *)tb_grow(v_lines) = tb_v3012; }
    { const char * tb_v3013 = "TB_API void (*tb_key_hook)(unsigned char sc) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3013; }
    { const char * tb_v3014 = "TB_API void tb_key_byte(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3014; }
    { const char * tb_v3015 = "    if (tb_key_hook) tb_key_hook(sc);\n"; *(const char * *)tb_grow(v_lines) = tb_v3015; }
    { const char * tb_v3016 = "    if (sc == 0x2A || sc == 0x36) { tb_kshift = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3016; }
    { const char * tb_v3017 = "    if (sc == 0xAA || sc == 0xB6) { tb_kshift = 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3017; }
    { const char * tb_v3018 = "    if (sc >= 58) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3018; }
    { const char * tb_v3019 = "    char ch = tb_kmap[tb_kshift][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v3019; }
    { const char * tb_v3020 = "    if (ch == 0 || (unsigned char)(tb_khead + 1) == tb_ktail) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3020; }
    { const char * tb_v3021 = "    tb_kq[tb_khead] = ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v3021; }
    { const char * tb_v3022 = "    tb_khead = (unsigned char)(tb_khead + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3022; }
    { const char * tb_v3023 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3023; }
    { const char * tb_v3024 = "TB_API void tb_key_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3024; }
    { const char * tb_v3025 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v3025; }
    { const char * tb_v3026 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3026; }
    { const char * tb_v3027 = "    unsigned char b = tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v3027; }
    { const char * tb_v3028 = "    if (st & 0x20) return;   // байт мыши (его ждёт прерывание 12)\n"; *(const char * *)tb_grow(v_lines) = tb_v3028; }
    { const char * tb_v3029 = "    tb_key_byte(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v3029; }
    { const char * tb_v3030 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3030; }
    { const char * tb_v3031 = "TB_API const char *tb_read_key(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3031; }
    { const char * tb_v3032 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3032; }
    { const char * tb_v3033 = "    const char *r = \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3033; }
    { const char * tb_v3034 = "    if (tb_ktail != tb_khead) { r = tb_ktext[(unsigned char)tb_kq[tb_ktail]]; tb_ktail = (unsigned char)(tb_ktail + 1); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3034; }
    { const char * tb_v3035 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
    { const char * tb_v3037 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3037; }
    { const char * tb_v3038 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3038; }
    { const char * tb_v3039 = "// --- страницы памяти (4 уровня): нижняя память — страницы по 4 КБ (адрес 0 и код защищены,\n"; *(const char * *)tb_grow(v_lines) = tb_v3039; }
    { const char * tb_v3040 = "// у стеков — пустая страница-сторож), выше — большие по 2 МБ (куча и свободная память) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3040; }
    { const char * tb_v3041 = "#define TB_LOW_PTS 32                                 // 32 таблицы × 2 МБ = нижние 64 МБ\n"; *(const char * *)tb_grow(v_lines) = tb_v3041; }
    { const char * tb_v3042 = "#define TB_MAX_GB 64                                  // память до 64 ГБ\n"; *(const char * *)tb_grow(v_lines) = tb_v3042; }
