    { const char * tb_v3046 = "TB_API uint64_t tb_pt[TB_LOW_PTS][512] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3046; }
    { const char * tb_v3047 = "TB_API uint64_t tb_ram_end = 0, tb_pg_next = 0, tb_pg_free = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3047; }
    { const char * tb_v3048 = "// таблицы на время загрузки: первые 4 ГБ большими страницами (их строит _start ещё в 32 битах)\n"; *(const char * *)tb_grow(v_lines) = tb_v3048; }
    { const char * tb_v3049 = "TB_API uint64_t tb_boot_pml4[512] __attribute__((aligned(4096), used));\n"; *(const char * *)tb_grow(v_lines) = tb_v3049; }
