    { const char * tb_v3164 = "// клетка (задача background) упала: только она и заканчивается, ядро и другие клетки живут.\n"; *(const char * *)tb_grow(v_lines) = tb_v3164; }
    { const char * tb_v3165 = "// Тот, кто её запустил, узнаёт это из .crashed (done == 2). Main и прерывание так не умеют:\n"; *(const char * *)tb_grow(v_lines) = tb_v3165; }
