    { const char * tb_v3677 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3677; }
    { const char * tb_v3678 = "TB_API long tb_win_sysconf(int what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "    (void)what;\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "    SYSTEM_INFO si;\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "    GetSystemInfo(&si);\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "    return (long)si.dwNumberOfProcessors;\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
