    { const char * tb_v3701 = "#define sysconf(x) tb_win_sysconf(x)\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "#define localtime_r(t, r) (localtime_s((r), (t)) == 0 ? (r) : 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
