    { const char * tb_v3706 = "// подсказки для clang / gcc: ошибка бывает редко, а tb_crash не возвращается\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "#if defined(__GNUC__)\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "#define TB_RARE(x) __builtin_expect(!!(x), 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "#define TB_COLD __attribute__((cold, noreturn, noinline))\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "#define TB_RARE(x) (x)\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
    { const char * tb_v3712 = "#define TB_COLD\n"; *(const char * *)tb_grow(v_lines) = tb_v3712; }
