    { const char * tb_v4670 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4670; }
    { const char * tb_v4671 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v4671; }
    { const char * tb_v4672 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v4672; }
    { const char * tb_v4673 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4673; }
    { const char * tb_v4674 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4674; }
    { const char * tb_v4675 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4675; }
    { const char * tb_v4676 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4676; }
    { const char * tb_v4677 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v4677; }
    { const char * tb_v4678 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v4678; }
    { const char * tb_v4679 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v4679; }
    { const char * tb_v4680 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v4680; }
    { const char * tb_v4681 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4681; }
    { const char * tb_v4682 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v4682; }
    { const char * tb_v4683 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v4683; }
    { const char * tb_v4684 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4684; }
    { const char * tb_v4685 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4685; }
    { const char * tb_v4686 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4686; }
    { const char * tb_v4687 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4687; }
    { const char * tb_v4688 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4688; }
    { const char * tb_v4689 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4689; }
    { const char * tb_v4690 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4690; }
    { const char * tb_v4691 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4691; }
    { const char * tb_v4692 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4692; }
    { const char * tb_v4693 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v4693; }
