    { const char * tb_v4849 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4849; }
    { const char * tb_v4850 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4850; }
