    { const char * tb_v4886 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4886; }
    { const char * tb_v4887 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4887; }
    { const char * tb_v4888 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v4888; }
    { const char * tb_v4889 = "TB_API int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4889; }
    { const char * tb_v4890 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4890; }
    { const char * tb_v4891 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v4891; }
    { const char * tb_v4892 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4892; }
    { const char * tb_v4893 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v4893; }
    { const char * tb_v4894 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v4894; }
    { const char * tb_v4895 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v4895; }
    { const char * tb_v4896 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4896; }
    { const char * tb_v4897 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4897; }
    { const char * tb_v4898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4898; }
    { const char * tb_v4899 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v4899; }
    { const char * tb_v4900 = "TB_API _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4900; }
