    { const char * tb_v4904 = "TB_INL void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; tb_u8c_clear(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4904; }
    { const char * tb_v4905 = "TB_INL void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4905; }
    { const char * tb_v4906 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v4906; }
    { const char * tb_v4907 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4907; }
