    { const char * tb_v4922 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4922; }
    { const char * tb_v4923 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v4923; }
    { const char * tb_v4924 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v4924; }
    { const char * tb_v4925 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v4925; }
    { const char * tb_v4926 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v4926; }
    { const char * tb_v4927 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v4927; }
    { const char * tb_v4928 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v4928; }
    { const char * tb_v4929 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v4929; }
    { const char * tb_v4930 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v4930; }
    { const char * tb_v4931 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v4931; }
    { const char * tb_v4932 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4932; }
