    { const char * tb_v4934 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4934; }
    { const char * tb_v4935 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4935; }
    { const char * tb_v4936 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4936; }
    { const char * tb_v4937 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4937; }
