    { const char * tb_v5065 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v5065; }
    { const char * tb_v5066 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5066; }
    { const char * tb_v5067 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v5067; }
    { const char * tb_v5068 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v5068; }
