    { const char * tb_v5680 = "    return tb_u8text(s + b, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v5680; }
    { const char * tb_v5681 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5681; }
    { const char * tb_v5682 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5682; }
    { const char * tb_v5683 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5683; }
    { const char * tb_v5684 = "    const unsigned char *p = (const unsigned char *)s + *i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5684; }
    { const char * tb_v5685 = "    if (*p < 0x80) return tb_chr(*p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5685; }
