    { const char * tb_v6030 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6030; }
    { const char * tb_v6031 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6031; }
    { const char * tb_v6032 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6032; }
    { const char * tb_v6033 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v6033; }
    { const char * tb_v6034 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v6034; }
    { const char * tb_v6035 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6035; }
    { const char * tb_v6036 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v6036; }
    { const char * tb_v6037 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v6037; }
    { const char * tb_v6038 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v6038; }
    { const char * tb_v6039 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6039; }
    { const char * tb_v6040 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v6040; }
    { const char * tb_v6041 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v6041; }
    { const char * tb_v6042 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v6042; }
    { const char * tb_v6043 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6043; }
    { const char * tb_v6044 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6044; }
    { const char * tb_v6045 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6045; }
    { const char * tb_v6046 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6046; }
    { const char * tb_v6047 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6047; }
    { const char * tb_v6048 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6048; }
    { const char * tb_v6049 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6049; }
    { const char * tb_v6050 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6050; }
    { const char * tb_v6051 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6051; }
    { const char * tb_v6052 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6052; }
    { const char * tb_v6053 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6053; }
    { const char * tb_v6054 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6054; }
    { const char * tb_v6055 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6055; }
    { const char * tb_v6056 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6056; }
    { const char * tb_v6057 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6057; }
    { const char * tb_v6058 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6058; }
    { const char * tb_v6059 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6059; }
    { const char * tb_v6060 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v6060; }
    { const char * tb_v6061 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6061; }
    { const char * tb_v6062 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v6062; }
    { const char * tb_v6063 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v6063; }
    { const char * tb_v6064 = "    while ((got = fread(buf + len, 1, cap - len - 1, p)) > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6064; }
    { const char * tb_v6065 = "        len += got;\n"; *(const char * *)tb_grow(v_lines) = tb_v6065; }
    { const char * tb_v6066 = "        if (len + 1 == cap) { buf = tb_resize(buf, cap, cap * 2); cap *= 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6066; }
    { const char * tb_v6067 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6067; }
    { const char * tb_v6068 = "    buf[len] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6068; }
    { const char * tb_v6069 = "    if (pclose(p) != 0) { tb_err = tb_cat(\"не получилось скачать (нет сети, нет curl или сервер ответил ошибкой): \", url); return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6069; }
