    { const char * tb_v6073 = "// ---------- JSON: json_get(текст, \"users.0.name\") и json_text(текст) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6073; }
    { const char * tb_v6074 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6074; }
    { const char * tb_v6075 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v6075; }
    { const char * tb_v6076 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6076; }
    { const char * tb_v6077 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6077; }
    { const char * tb_v6078 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6078; }
    { const char * tb_v6079 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6079; }
    { const char * tb_v6080 = "        while (*p && *p != '\"') { if (*p == '\\\\' && p[1]) p++; p++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6080; }
    { const char * tb_v6081 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6081; }
    { const char * tb_v6082 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6082; }
    { const char * tb_v6083 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6083; }
    { const char * tb_v6084 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6084; }
    { const char * tb_v6085 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6085; }
    { const char * tb_v6086 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6086; }
    { const char * tb_v6087 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6087; }
    { const char * tb_v6088 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6088; }
    { const char * tb_v6089 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6089; }
    { const char * tb_v6090 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6090; }
    { const char * tb_v6091 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6091; }
    { const char * tb_v6092 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6092; }
    { const char * tb_v6093 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v6093; }
    { const char * tb_v6094 = "    while (*p && *p != ',' && *p != '}' && *p != ']' && *p != ' ' && *p != '\\n' && *p != '\\r' && *p != '\\t') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6094; }
    { const char * tb_v6095 = "    return p == s ? 0 : p;\n"; *(const char * *)tb_grow(v_lines) = tb_v6095; }
    { const char * tb_v6096 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6096; }
    { const char * tb_v6097 = "TB_API int tb_js_hex(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6097; }
    { const char * tb_v6098 = "    int v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6098; }
    { const char * tb_v6099 = "    for (int i = 0; i < 4; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6099; }
    { const char * tb_v6100 = "        char ch = p[i]; v <<= 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v6100; }
    { const char * tb_v6101 = "        if (ch >= '0' && ch <= '9') v |= ch - '0';\n"; *(const char * *)tb_grow(v_lines) = tb_v6101; }
    { const char * tb_v6102 = "        else if (ch >= 'a' && ch <= 'f') v |= ch - 'a' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v6102; }
    { const char * tb_v6103 = "        else if (ch >= 'A' && ch <= 'F') v |= ch - 'A' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v6103; }
    { const char * tb_v6104 = "        else return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6104; }
    { const char * tb_v6105 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6105; }
    { const char * tb_v6106 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6106; }
    { const char * tb_v6107 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6107; }
    { const char * tb_v6108 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v6108; }
    { const char * tb_v6109 = "TB_API const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6109; }
    { const char * tb_v6110 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6110; }
    { const char * tb_v6111 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6111; }
    { const char * tb_v6112 = "    char *out = tb_tmem(e - p + 1), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v6112; }
    { const char * tb_v6113 = "    p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6113; }
    { const char * tb_v6114 = "    while (*p != '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6114; }
    { const char * tb_v6115 = "        if (*p != '\\\\') { *o++ = *p++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6115; }
    { const char * tb_v6116 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6116; }
    { const char * tb_v6117 = "        char ch = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6117; }
    { const char * tb_v6118 = "        if (ch == 'n') *o++ = '\\n'; else if (ch == 't') *o++ = '\\t'; else if (ch == 'r') *o++ = '\\r';\n"; *(const char * *)tb_grow(v_lines) = tb_v6118; }
    { const char * tb_v6119 = "        else if (ch == 'b') *o++ = '\\b'; else if (ch == 'f') *o++ = '\\f';\n"; *(const char * *)tb_grow(v_lines) = tb_v6119; }
    { const char * tb_v6120 = "        else if (ch == 'u') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6120; }
    { const char * tb_v6121 = "            int cp = tb_js_hex(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6121; }
    { const char * tb_v6122 = "            if (cp < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6122; }
    { const char * tb_v6123 = "            p += 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v6123; }
    { const char * tb_v6124 = "            if (cp >= 0xD800 && cp < 0xDC00 && p[0] == '\\\\' && p[1] == 'u') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6124; }
    { const char * tb_v6125 = "                int lo = tb_js_hex(p + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v6125; }
    { const char * tb_v6126 = "                if (lo >= 0xDC00 && lo < 0xE000) { cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00); p += 6; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6126; }
    { const char * tb_v6127 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6127; }
    { const char * tb_v6128 = "            if (cp < 0x80) *o++ = (char)cp;\n"; *(const char * *)tb_grow(v_lines) = tb_v6128; }
    { const char * tb_v6129 = "            else if (cp < 0x800) { *o++ = (char)(0xC0 | (cp >> 6)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6129; }
    { const char * tb_v6130 = "            else if (cp < 0x10000) { *o++ = (char)(0xE0 | (cp >> 12)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6130; }
    { const char * tb_v6131 = "            else { *o++ = (char)(0xF0 | (cp >> 18)); *o++ = (char)(0x80 | ((cp >> 12) & 63)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6131; }
    { const char * tb_v6132 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6132; }
    { const char * tb_v6133 = "        else *o++ = ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v6133; }
