    { const char * tb_v6492 = "// цвет с непрозрачностью a: 255 — сплошной (как rgb), 0 — не виден. Рисование смешивает его с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v6492; }
    { const char * tb_v6493 = "TB_API long long tb_rgba(long long r, long long g, long long b, long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6493; }
