    { const char * tb_v6722 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6722; }
    { const char * tb_v6723 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6723; }
    { const char * tb_v6724 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v6724; }
    { const char * tb_v6725 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6725; }
    { const char * tb_v6726 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6726; }
    { const char * tb_v6727 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v6727; }
    { const char * tb_v6728 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6728; }
    { const char * tb_v6729 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6729; }
    { const char * tb_v6730 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6730; }
    { const char * tb_v6731 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v6731; }
    { const char * tb_v6732 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6732; }
    { const char * tb_v6733 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6733; }
