    { const char * tb_v6746 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6746; }
    { const char * tb_v6747 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v6747; }
    { const char * tb_v6748 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6748; }
    { const char * tb_v6749 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6749; }
