    { const char * tb_v6751 = "        if (at < (unsigned long long)d->vals->len) __builtin_prefetch(d->vals->data + at * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6751; }
    { const char * tb_v6752 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6752; }
    { const char * tb_v6753 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6753; }
    { const char * tb_v6754 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6754; }
