    { const char * tb_v6756 = "        if (o < (unsigned long long)d->npos) { __builtin_prefetch(&d->pos[o]); return o; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6756; }
    { const char * tb_v6757 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6757; }
