    { const char * tb_v6760 = "    __builtin_prefetch(&d->slots[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6760; }
    { const char * tb_v6761 = "    return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v6761; }
    { const char * tb_v6762 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6762; }
    { const char * tb_v6763 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v6763; }
    { const char * tb_v6764 = "TB_INL void tb_dpre2(tb_dict *d, unsigned long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6764; }
    { const char * tb_v6765 = "    if (i == ~0ULL || d->mode == 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6765; }
    { const char * tb_v6766 = "    long long s = d->mode == 2 ? d->pos[i] : (d->slots[i] & TB_DAT);\n"; *(const char * *)tb_grow(v_lines) = tb_v6766; }
    { const char * tb_v6767 = "    if (s != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6767; }
    { const char * tb_v6768 = "        if (d->mode == 0) __builtin_prefetch(d->keys->data + (s - 1) * d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6768; }
    { const char * tb_v6769 = "        __builtin_prefetch(d->vals->data + (s - 1) * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6769; }
    { const char * tb_v6770 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6770; }
    { const char * tb_v6771 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6771; }
    { const char * tb_v6772 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v6772; }
    { const char * tb_v6773 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6773; }
    { const char * tb_v6774 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6774; }
    { const char * tb_v6775 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6775; }
    { const char * tb_v6776 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6776; }
    { const char * tb_v6777 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6777; }
    { const char * tb_v6778 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6778; }
    { const char * tb_v6779 = "    void *r = tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6779; }
    { const char * tb_v6780 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6780; }
    { const char * tb_v6781 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6781; }
    { const char * tb_v6782 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6782; }
    { const char * tb_v6783 = "TB_API void *tb_cold_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6783; }
    { const char * tb_v6784 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6784; }
    { const char * tb_v6785 = "    void *r = tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6785; }
    { const char * tb_v6786 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6786; }
    { const char * tb_v6787 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6787; }
    { const char * tb_v6788 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6788; }
    { const char * tb_v6789 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6789; }
    { const char * tb_v6790 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v6790; }
    { const char * tb_v6791 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6791; }
    { const char * tb_v6792 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6792; }
    { const char * tb_v6793 = "    return tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6793; }
    { const char * tb_v6794 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6794; }
    { const char * tb_v6795 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6795; }
    { const char * tb_v6796 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6796; }
    { const char * tb_v6797 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6797; }
    { const char * tb_v6798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6798; }
    { const char * tb_v6799 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6799; }
    { const char * tb_v6800 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6800; }
    { const char * tb_v6801 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v6801; }
    { const char * tb_v6802 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6802; }
    { const char * tb_v6803 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6803; }
    { const char * tb_v6804 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6804; }
    { const char * tb_v6805 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6805; }
    { const char * tb_v6806 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v6806; }
    { const char * tb_v6807 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6807; }
    { const char * tb_v6808 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v6808; }
    { const char * tb_v6809 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6809; }
    { const char * tb_v6810 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6810; }
    { const char * tb_v6811 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v6811; }
    { const char * tb_v6812 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6812; }
    { const char * tb_v6813 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v6813; }
    { const char * tb_v6814 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6814; }
    { const char * tb_v6815 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6815; }
    { const char * tb_v6816 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6816; }
    { const char * tb_v6817 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6817; }
    { const char * tb_v6818 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6818; }
    { const char * tb_v6819 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6819; }
    { const char * tb_v6820 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6820; }
    { const char * tb_v6821 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6821; }
    { const char * tb_v6822 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v6822; }
    { const char * tb_v6823 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6823; }
    { const char * tb_v6824 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6824; }
    { const char * tb_v6825 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6825; }
    { const char * tb_v6826 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6826; }
    { const char * tb_v6827 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v6827; }
    { const char * tb_v6828 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6828; }
    { const char * tb_v6829 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6829; }
    { const char * tb_v6830 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6830; }
    { const char * tb_v6831 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6831; }
    { const char * tb_v6832 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6832; }
    { const char * tb_v6833 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6833; }
    { const char * tb_v6834 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6834; }
    { const char * tb_v6835 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v6835; }
    { const char * tb_v6836 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6836; }
    { const char * tb_v6837 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6837; }
    { const char * tb_v6838 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6838; }
    { const char * tb_v6839 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v6839; }
    { const char * tb_v6840 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v6840; }
    { const char * tb_v6841 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v6841; }
    { const char * tb_v6842 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6842; }
    { const char * tb_v6843 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6843; }
    { const char * tb_v6844 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v6844; }
    { const char * tb_v6845 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v6845; }
    { const char * tb_v6846 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6846; }
    { const char * tb_v6847 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6847; }
    { const char * tb_v6848 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6848; }
    { const char * tb_v6849 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6849; }
    { const char * tb_v6850 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6850; }
    { const char * tb_v6851 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v6851; }
    { const char * tb_v6852 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6852; }
    { const char * tb_v6853 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6853; }
    { const char * tb_v6854 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
    { const char * tb_v6855 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6855; }
    { const char * tb_v6856 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6856; }
    { const char * tb_v6857 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6857; }
    { const char * tb_v6858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6858; }
    { const char * tb_v6859 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6859; }
    { const char * tb_v6860 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v6860; }
    { const char * tb_v6861 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v6861; }
    { const char * tb_v6862 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6862; }
    { const char * tb_v6863 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6863; }
    { const char * tb_v6864 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6864; }
    { const char * tb_v6865 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6865; }
