    { const char * tb_v7149 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v7149; }
    { const char * tb_v7150 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7150; }
    { const char * tb_v7151 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v7151; }
    { const char * tb_v7152 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v7152; }
    { const char * tb_v7153 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7153; }
    { const char * tb_v7154 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7154; }
    { const char * tb_v7155 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7155; }
    { const char * tb_v7156 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7156; }
    { const char * tb_v7157 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7157; }
    { const char * tb_v7158 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7158; }
    { const char * tb_v7159 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v7159; }
    { const char * tb_v7160 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v7160; }
    { const char * tb_v7161 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v7161; }
    { const char * tb_v7162 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v7162; }
    { const char * tb_v7163 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v7163; }
    { const char * tb_v7164 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v7164; }
    { const char * tb_v7165 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v7165; }
    { const char * tb_v7166 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7166; }
    { const char * tb_v7167 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v7167; }
    { const char * tb_v7168 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7168; }
    { const char * tb_v7169 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7169; }
    { const char * tb_v7170 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v7170; }
    { const char * tb_v7171 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v7171; }
    { const char * tb_v7172 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7172; }
    { const char * tb_v7173 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v7173; }
    { const char * tb_v7174 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7174; }
    { const char * tb_v7175 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v7175; }
    { const char * tb_v7176 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7176; }
    { const char * tb_v7177 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7177; }
    { const char * tb_v7178 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v7178; }
    { const char * tb_v7179 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7179; }
    { const char * tb_v7180 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v7180; }
    { const char * tb_v7181 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v7181; }
    { const char * tb_v7182 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7182; }
    { const char * tb_v7183 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v7183; }
    { const char * tb_v7184 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7184; }
    { const char * tb_v7185 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7185; }
    { const char * tb_v7186 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7186; }
    { const char * tb_v7187 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v7187; }
    { const char * tb_v7188 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7188; }
    { const char * tb_v7189 = "        char buf[400];\n"; *(const char * *)tb_grow(v_lines) = tb_v7189; }
    { const char * tb_v7190 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v7190; }
    { const char * tb_v7191 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v7191; }
    { const char * tb_v7192 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7192; }
    { const char * tb_v7193 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7193; }
    { const char * tb_v7194 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7194; }
    { const char * tb_v7195 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v7195; }
    { const char * tb_v7196 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7196; }
    { const char * tb_v7197 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7197; }
    { const char * tb_v7198 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7198; }
    { const char * tb_v7199 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v7199; }
    { const char * tb_v7200 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v7200; }
    { const char * tb_v7201 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7201; }
    { const char * tb_v7202 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v7202; }
    { const char * tb_v7203 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v7203; }
    { const char * tb_v7204 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v7204; }
    { const char * tb_v7205 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7205; }
    { const char * tb_v7206 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v7206; }
    { const char * tb_v7207 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7207; }
    { const char * tb_v7208 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v7208; }
    { const char * tb_v7209 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7209; }
    { const char * tb_v7210 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v7210; }
    { const char * tb_v7211 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v7211; }
    { const char * tb_v7212 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7212; }
    { const char * tb_v7213 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7213; }
    { const char * tb_v7214 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v7214; }
    { const char * tb_v7215 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7215; }
    { const char * tb_v7216 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7216; }
    { const char * tb_v7217 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v7217; }
    { const char * tb_v7218 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7218; }
    { const char * tb_v7219 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7219; }
    { const char * tb_v7220 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v7220; }
    { const char * tb_v7221 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7221; }
    { const char * tb_v7222 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v7222; }
    { const char * tb_v7223 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7223; }
    { const char * tb_v7224 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v7224; }
    { const char * tb_v7225 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7225; }
    { const char * tb_v7226 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7226; }
    { const char * tb_v7227 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7227; }
    { const char * tb_v7228 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v7228; }
    { const char * tb_v7229 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7229; }
    { const char * tb_v7230 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7230; }
    { const char * tb_v7231 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v7231; }
    { const char * tb_v7232 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7232; }
    { const char * tb_v7233 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v7233; }
    { const char * tb_v7234 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7234; }
    { const char * tb_v7235 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7235; }
    { const char * tb_v7236 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7236; }
    { const char * tb_v7237 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v7237; }
    { const char * tb_v7238 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7238; }
    { const char * tb_v7239 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7239; }
    { const char * tb_v7240 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7240; }
    { const char * tb_v7241 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7241; }
    { const char * tb_v7242 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v7242; }
    { const char * tb_v7243 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7243; }
    { const char * tb_v7244 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7244; }
    { const char * tb_v7245 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v7245; }
    { const char * tb_v7246 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v7246; }
    { const char * tb_v7247 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v7247; }
    { const char * tb_v7248 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7248; }
    { const char * tb_v7249 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7249; }
    { const char * tb_v7250 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v7250; }
    { const char * tb_v7251 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v7251; }
    { const char * tb_v7252 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v7252; }
    { const char * tb_v7253 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
    { const char * tb_v7254 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7254; }
    { const char * tb_v7255 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v7255; }
    { const char * tb_v7256 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v7256; }
    { const char * tb_v7257 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7257; }
    { const char * tb_v7258 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v7258; }
    { const char * tb_v7259 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7259; }
    { const char * tb_v7260 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7260; }
    { const char * tb_v7261 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7261; }
    { const char * tb_v7262 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7262; }
    { const char * tb_v7263 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7263; }
    { const char * tb_v7264 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7264; }
    { const char * tb_v7265 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
    { const char * tb_v7266 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
    { const char * tb_v7267 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v7267; }
    { const char * tb_v7268 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v7268; }
    { const char * tb_v7269 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v7269; }
    { const char * tb_v7270 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7270; }
    { const char * tb_v7271 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7271; }
    { const char * tb_v7272 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "    if (nb == 4) return *(volatile uint32_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
    { const char * tb_v7274 = "    return *(volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7274; }
    { const char * tb_v7275 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7275; }
    { const char * tb_v7276 = "static inline void tb_shape_put(uintptr_t p, int nb, uint64_t v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7276; }
    { const char * tb_v7277 = "    if (nb == 1) *(volatile uint8_t *)p = (uint8_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7277; }
    { const char * tb_v7278 = "    else if (nb == 2) *(volatile uint16_t *)p = (uint16_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7278; }
    { const char * tb_v7279 = "    else if (nb == 4) *(volatile uint32_t *)p = (uint32_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7279; }
    { const char * tb_v7280 = "    else *(volatile uint64_t *)p = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7280; }
    { const char * tb_v7281 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7281; }
    { const char * tb_v7282 = "static inline uint64_t tb_shape_swap(uint64_t v, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7282; }
    { const char * tb_v7283 = "    if (nb == 2) return __builtin_bswap16((uint16_t)v);\n"; *(const char * *)tb_grow(v_lines) = tb_v7283; }
    { const char * tb_v7284 = "    if (nb == 4) return __builtin_bswap32((uint32_t)v);\n"; *(const char * *)tb_grow(v_lines) = tb_v7284; }
    { const char * tb_v7285 = "    if (nb == 8) return __builtin_bswap64(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v7285; }
    { const char * tb_v7286 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7286; }
    { const char * tb_v7287 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7287; }
    { const char * tb_v7288 = "TB_INL long long tb_shape_at(long long a) { return a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7288; }
    { const char * tb_v7289 = "TB_API long long tb_shape_get(long long a, long long k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7289; }
    { const char * tb_v7290 = "    uintptr_t p = (uintptr_t)(a + (k >> 20));\n"; *(const char * *)tb_grow(v_lines) = tb_v7290; }
    { const char * tb_v7291 = "    int nb = (int)(k & 15), bo = (int)((k >> 6) & 63), bn = (int)((k >> 12) & 127);\n"; *(const char * *)tb_grow(v_lines) = tb_v7291; }
    { const char * tb_v7292 = "    if (!nb) return (long long)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7292; }
    { const char * tb_v7293 = "    TB_TOUCH(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v7293; }
    { const char * tb_v7294 = "    uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
