    { const char * tb_v7664 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v7664; }
    { const char * tb_v7665 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7665; }
    { const char * tb_v7666 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v7666; }
    { const char * tb_v7667 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7667; }
    { const char * tb_v7668 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v7668; }
    { const char * tb_v7669 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7669; }
    { const char * tb_v7670 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7670; }
    { const char * tb_v7671 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7671; }
    { const char * tb_v7672 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7672; }
    { const char * tb_v7673 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7673; }
    { const char * tb_v7674 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7674; }
    { const char * tb_v7675 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7675; }
    { const char * tb_v7676 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7676; }
    { const char * tb_v7677 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7677; }
    { const char * tb_v7678 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v7678; }
    { const char * tb_v7679 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v7679; }
    { const char * tb_v7680 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7680; }
    { const char * tb_v7681 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7681; }
    { const char * tb_v7682 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v7682; }
    { const char * tb_v7683 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v7683; }
    { const char * tb_v7684 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v7684; }
    { const char * tb_v7685 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7685; }
    { const char * tb_v7686 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7686; }
    { const char * tb_v7687 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7687; }
    { const char * tb_v7688 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v7688; }
    { const char * tb_v7689 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7689; }
    { const char * tb_v7690 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7690; }
    { const char * tb_v7691 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7691; }
    { const char * tb_v7692 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7692; }
    { const char * tb_v7693 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7693; }
    { const char * tb_v7694 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7694; }
    { const char * tb_v7695 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7695; }
    { const char * tb_v7696 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7696; }
    { const char * tb_v7697 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7697; }
    { const char * tb_v7698 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7698; }
    { const char * tb_v7699 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7699; }
    { const char * tb_v7700 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7700; }
    { const char * tb_v7701 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7701; }
    { const char * tb_v7702 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7702; }
    { const char * tb_v7703 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v7703; }
    { const char * tb_v7704 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7704; }
    { const char * tb_v7705 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7705; }
    { const char * tb_v7706 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v7706; }
    { const char * tb_v7707 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v7707; }
    { const char * tb_v7708 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7708; }
    { const char * tb_v7709 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v7709; }
    { const char * tb_v7710 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v7710; }
    { const char * tb_v7711 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v7711; }
    { const char * tb_v7712 = "       TB_K_CMD = 1, TB_K_CTRL = 2, TB_K_ALT = 3, TB_K_DEL = 4, TB_K_HOME = 5, TB_K_END = 6, TB_K_PGUP = 7,\n"; *(const char * *)tb_grow(v_lines) = tb_v7712; }
    { const char * tb_v7713 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v7713; }
    { const char * tb_v7714 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7714; }
    { const char * tb_v7715 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v7715; }
    { const char * tb_v7716 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v7716; }
    { const char * tb_v7717 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v7717; }
    { const char * tb_v7718 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v7718; }
    { const char * tb_v7719 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7719; }
    { const char * tb_v7720 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7720; }
    { const char * tb_v7721 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7721; }
    { const char * tb_v7722 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7722; }
    { const char * tb_v7723 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7723; }
    { const char * tb_v7724 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7724; }
    { const char * tb_v7725 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7725; }
    { const char * tb_v7726 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7726; }
    { const char * tb_v7727 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7727; }
    { const char * tb_v7728 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7728; }
    { const char * tb_v7729 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7729; }
