    { const char * tb_v8362 = "// картинка из байтов в памяти (PNG, JPEG, BMP, GIF) → номер картинки; -1 и tb_err — не вышло\n"; *(const char * *)tb_grow(v_lines) = tb_v8362; }
    { const char * tb_v8363 = "TB_API long long tb_image_add(const unsigned char *d, size_t sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8363; }
