    { const char * tb_v8408 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v8408; }
    { const char * tb_v8409 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v8409; }
    { const char * tb_v8410 = "    if (!all || !list) { tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8410; }
