    { const char * tb_v8432 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8432; }
    { const char * tb_v8433 = "// снимок кадра (что нарисовано сейчас) — новая картинка; потом draw_image рисует её за один раз\n"; *(const char * *)tb_grow(v_lines) = tb_v8433; }
    { const char * tb_v8434 = "TB_API long long tb_screen_image(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8434; }
    { const char * tb_v8435 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v8435; }
    { const char * tb_v8436 = "    if (!tb_px) { tb_err = \"окно ещё не открыто\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8436; }
    { const char * tb_v8437 = "    size_t n = (size_t)tb_gw * tb_gh, need = tb_imgpx_n + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8437; }
    { const char * tb_v8438 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8438; }
    { const char * tb_v8439 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8439; }
    { const char * tb_v8440 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v8440; }
