    { const char * tb_v8442 = "    if (!all || !list) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8442; }
    { const char * tb_v8443 = "    for (size_t i = 0; i < n; i++) tb_imgpx[tb_imgpx_n + i] = tb_px[i] | 0xFF000000u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8443; }
    { const char * tb_v8444 = "    tb_imgs[tb_nimg].w = tb_gw; tb_imgs[tb_nimg].h = tb_gh; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8444; }
    { const char * tb_v8445 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8445; }
    { const char * tb_v8446 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8446; }
    { const char * tb_v8447 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8447; }
    { const char * tb_v8448 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8448; }
    { const char * tb_v8449 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8449; }
    { const char * tb_v8450 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8450; }
    { const char * tb_v8451 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8451; }
    { const char * tb_v8452 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v8452; }
    { const char * tb_v8453 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v8453; }
    { const char * tb_v8454 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8454; }
    { const char * tb_v8455 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8455; }
    { const char * tb_v8456 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8456; }
    { const char * tb_v8457 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8457; }
    { const char * tb_v8458 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8458; }
    { const char * tb_v8459 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8459; }
    { const char * tb_v8460 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8460; }
    { const char * tb_v8461 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8461; }
    { const char * tb_v8462 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8462; }
    { const char * tb_v8463 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8463; }
    { const char * tb_v8464 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v8464; }
    { const char * tb_v8465 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8465; }
    { const char * tb_v8466 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8466; }
    { const char * tb_v8467 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8467; }
    { const char * tb_v8468 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v8468; }
    { const char * tb_v8469 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8469; }
    { const char * tb_v8470 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8470; }
    { const char * tb_v8471 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8471; }
    { const char * tb_v8472 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v8472; }
    { const char * tb_v8473 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8473; }
    { const char * tb_v8474 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8474; }
    { const char * tb_v8475 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8475; }
    { const char * tb_v8476 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v8476; }
    { const char * tb_v8477 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8477; }
    { const char * tb_v8478 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v8478; }
    { const char * tb_v8479 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8479; }
    { const char * tb_v8480 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8480; }
    { const char * tb_v8481 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8481; }
    { const char * tb_v8482 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8482; }
    { const char * tb_v8483 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8483; }
    { const char * tb_v8484 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8484; }
    { const char * tb_v8485 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v8485; }
    { const char * tb_v8486 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8486; }
    { const char * tb_v8487 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v8487; }
    { const char * tb_v8488 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8488; }
    { const char * tb_v8489 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v8489; }
    { const char * tb_v8490 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8490; }
    { const char * tb_v8491 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8491; }
    { const char * tb_v8492 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8492; }
    { const char * tb_v8493 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8493; }
    { const char * tb_v8494 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8494; }
    { const char * tb_v8495 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8495; }
    { const char * tb_v8496 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v8496; }
    { const char * tb_v8497 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8497; }
    { const char * tb_v8498 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v8498; }
    { const char * tb_v8499 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8499; }
    { const char * tb_v8500 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8500; }
    { const char * tb_v8501 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8501; }
    { const char * tb_v8502 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8502; }
    { const char * tb_v8503 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v8503; }
    { const char * tb_v8504 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8504; }
    { const char * tb_v8505 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8505; }
    { const char * tb_v8506 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v8506; }
    { const char * tb_v8507 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v8507; }
    { const char * tb_v8508 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8508; }
    { const char * tb_v8509 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8509; }
    { const char * tb_v8510 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8510; }
    { const char * tb_v8511 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v8511; }
    { const char * tb_v8512 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8512; }
    { const char * tb_v8513 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v8513; }
    { const char * tb_v8514 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8514; }
    { const char * tb_v8515 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v8515; }
    { const char * tb_v8516 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8516; }
    { const char * tb_v8517 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v8517; }
    { const char * tb_v8518 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8518; }
    { const char * tb_v8519 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8519; }
    { const char * tb_v8520 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8520; }
    { const char * tb_v8521 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8521; }
    { const char * tb_v8522 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8522; }
    { const char * tb_v8523 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v8523; }
    { const char * tb_v8524 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8524; }
    { const char * tb_v8525 = "        if (u > tb_u16(f, ends + 2 * i)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8525; }
    { const char * tb_v8526 = "        unsigned s = tb_u16(f, starts + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8526; }
    { const char * tb_v8527 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8527; }
    { const char * tb_v8528 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8528; }
    { const char * tb_v8529 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8529; }
    { const char * tb_v8530 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v8530; }
    { const char * tb_v8531 = "        return g ? (g + delta) & 0xFFFF : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8531; }
    { const char * tb_v8532 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8532; }
    { const char * tb_v8533 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8533; }
    { const char * tb_v8534 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8534; }
    { const char * tb_v8535 = "static double tb_ttf_adv(const tb_font_t *f, unsigned g) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8535; }
    { const char * tb_v8536 = "    unsigned i = (int)g < f->nhm ? g : (unsigned)f->nhm - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8536; }
    { const char * tb_v8537 = "    return tb_u16(f, f->hmtx + 4 * (size_t)i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8537; }
    { const char * tb_v8538 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8538; }
    { const char * tb_v8539 = "static size_t tb_ttf_gpos(const tb_font_t *f, unsigned g, size_t *len) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8539; }
    { const char * tb_v8540 = "    if ((int)g >= f->nglyphs) { *len = 0; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8540; }
    { const char * tb_v8541 = "    size_t a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v8541; }
    { const char * tb_v8542 = "    if (f->locfmt == 0) { a = 2 * (size_t)tb_u16(f, f->loca + 2 * g); b = 2 * (size_t)tb_u16(f, f->loca + 2 * g + 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8542; }
    { const char * tb_v8543 = "    else { a = tb_u32(f, f->loca + 4 * g); b = tb_u32(f, f->loca + 4 * g + 4); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8543; }
    { const char * tb_v8544 = "    *len = b > a ? b - a : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8544; }
    { const char * tb_v8545 = "    return f->glyf + a;\n"; *(const char * *)tb_grow(v_lines) = tb_v8545; }
    { const char * tb_v8546 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8546; }
    { const char * tb_v8547 = "// контур буквы → отрезки (в точках экрана, y вниз); m — матрица шрифт → экран: x' = m0 x + m2 y + m4, y' = m1 x + m3 y + m5\n"; *(const char * *)tb_grow(v_lines) = tb_v8547; }
    { const char * tb_v8548 = "typedef struct { float *e; int n, cap; } tb_edges;\n"; *(const char * *)tb_grow(v_lines) = tb_v8548; }
    { const char * tb_v8549 = "static void tb_edge(tb_edges *E, double x0, double y0, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8549; }
    { const char * tb_v8550 = "    if (y0 == y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8550; }
    { const char * tb_v8551 = "    if (E->n == E->cap) { E->cap = E->cap ? E->cap * 2 : 256; E->e = realloc(E->e, (size_t)E->cap * 4 * sizeof(float)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8551; }
    { const char * tb_v8552 = "    float *p = E->e + 4 * E->n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8552; }
    { const char * tb_v8553 = "    p[0] = (float)x0; p[1] = (float)y0; p[2] = (float)x1; p[3] = (float)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8553; }
    { const char * tb_v8554 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8554; }
    { const char * tb_v8555 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8555; }
    { const char * tb_v8556 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8556; }
    { const char * tb_v8557 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8557; }
    { const char * tb_v8558 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v8558; }
    { const char * tb_v8559 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8559; }
