    { const char * tb_v8877 = "TB_API int tb_mlock = 0, tb_mseen = 0, tb_mwarp = 0, tb_cursor_prog = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8877; }
    { const char * tb_v8878 = "TB_API void tb_gfx_fullscreen(int on);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8878; }
    { const char * tb_v8879 = "// меню в строке системы (1.3): Mac — верхняя строка экрана, Windows — полоса меню окна, Linux — нет\n"; *(const char * *)tb_grow(v_lines) = tb_v8879; }
    { const char * tb_v8880 = "#define TB_MENU_MAX 256\n"; *(const char * *)tb_grow(v_lines) = tb_v8880; }
