    { const char * tb_v8882 = "TB_API int tb_gfx_menu_add(int id, const char *top, const char *item, const char *key, int mods);\n"; *(const char * *)tb_grow(v_lines) = tb_v8882; }
    { const char * tb_v8883 = "TB_API int tb_gfx_menu_native(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v8883; }
    { const char * tb_v8884 = "// команды правки текста от системы (1.3): Mac сам решает, что значит клавиша (Option+← — moveWordLeft:)\n"; *(const char * *)tb_grow(v_lines) = tb_v8884; }
    { const char * tb_v8885 = "TB_API char tb_tkeys[2048];\n"; *(const char * *)tb_grow(v_lines) = tb_v8885; }
    { const char * tb_v8886 = "TB_API int tb_ntkeys = 0, tb_tkeys_on = 0;   // on: система присылает команды (Mac)\n"; *(const char * *)tb_grow(v_lines) = tb_v8886; }
    { const char * tb_v8887 = "TB_API void tb_tkeys_add(const char *name) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8887; }
    { const char * tb_v8888 = "    size_t n = strlen(name);\n"; *(const char * *)tb_grow(v_lines) = tb_v8888; }
    { const char * tb_v8889 = "    if (!n || !strcmp(name, \"noop:\") || tb_ntkeys + (int)n + 2 >= (int)sizeof tb_tkeys) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8889; }
    { const char * tb_v8890 = "    if (tb_ntkeys) tb_tkeys[tb_ntkeys++] = ' ';\n"; *(const char * *)tb_grow(v_lines) = tb_v8890; }
    { const char * tb_v8891 = "    memcpy(tb_tkeys + tb_ntkeys, name, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v8891; }
    { const char * tb_v8892 = "    tb_ntkeys += (int)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8892; }
    { const char * tb_v8893 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8893; }
    { const char * tb_v8894 = "TB_API void tb_gfx_lock(int on);\n"; *(const char * *)tb_grow(v_lines) = tb_v8894; }
    { const char * tb_v8895 = "// мышь в точке (x, y) окна: копим сдвиг. Захвачена — меряем от середины окна, мышь потом вернётся туда\n"; *(const char * *)tb_grow(v_lines) = tb_v8895; }
    { const char * tb_v8896 = "TB_API void tb_mouse_at(int x, int y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8896; }
    { const char * tb_v8897 = "    if (tb_mlock) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8897; }
    { const char * tb_v8898 = "        int cx = tb_gw / 2, cy = tb_gh / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8898; }
    { const char * tb_v8899 = "        if (x == cx && y == cy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8899; }
    { const char * tb_v8900 = "        tb_mdx += x - cx; tb_mdy += y - cy; tb_mwarp = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8900; }
    { const char * tb_v8901 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8901; }
    { const char * tb_v8902 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8902; }
    { const char * tb_v8903 = "    if (tb_mseen) { tb_mdx += x - tb_mx; tb_mdy += y - tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8903; }
    { const char * tb_v8904 = "    tb_mseen = 1; tb_mx = x; tb_my = y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8904; }
    { const char * tb_v8905 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8905; }
    { const char * tb_v8906 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v8906; }
    { const char * tb_v8907 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8907; }
    { const char * tb_v8908 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8908; }
    { const char * tb_v8909 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8909; }
    { const char * tb_v8910 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8910; }
    { const char * tb_v8911 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8911; }
    { const char * tb_v8912 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v8912; }
    { const char * tb_v8913 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8913; }
    { const char * tb_v8914 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v8914; }
    { const char * tb_v8915 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8915; }
    { const char * tb_v8916 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8916; }
    { const char * tb_v8917 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8917; }
    { const char * tb_v8918 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, tb_tr(\"окно: рисует %s\\n\"), what);\n"; *(const char * *)tb_grow(v_lines) = tb_v8918; }
    { const char * tb_v8919 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8919; }
    { const char * tb_v8920 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8920; }
    { const char * tb_v8921 = "    fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\"), tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v8921; }
    { const char * tb_v8922 = "    if (tb_gpu_shskip) fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров со своими шейдерами (не сверялись): %lld\\n\"), tb_gpu_shskip);\n"; *(const char * *)tb_grow(v_lines) = tb_v8922; }
    { const char * tb_v8923 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8923; }
    { const char * tb_v8924 = "// ---- gpu func (1.3): шейдеры программы — их собрал компилятор Tachbit из gpu func ----\n"; *(const char * *)tb_grow(v_lines) = tb_v8924; }
    { const char * tb_v8925 = "// У каждого: имя, вид (0 — углы, 1 — точка), функция для процессора, SPIR-V, имена настроек по порядку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8925; }
    { const char * tb_v8926 = "// Metal берёт все шейдеры из одного текста tb_sh_msl. Сетка со своим шейдером рисуется обычными\n"; *(const char * *)tb_grow(v_lines) = tb_v8926; }
    { const char * tb_v8927 = "// дробными числами (не точка в точку с процессором): в пачке это фигура m = 7 — x0 номер записи,\n"; *(const char * *)tb_grow(v_lines) = tb_v8927; }
    { const char * tb_v8928 = "// y0 шейдер углов, x1 шейдер точки, y1 сколько углов; углы сетки лежат в своём буфере видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v8928; }
    { const char * tb_v8929 = "// R — своя запись draw_mesh (лампы, картинки, тени), T — точки всех картинок (tb_imgpx), S — карты теней (tb_shm)\n"; *(const char * *)tb_grow(v_lines) = tb_v8929; }
    { const char * tb_v8930 = "typedef void (*tb_shfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io);\n"; *(const char * *)tb_grow(v_lines) = tb_v8930; }
    { const char * tb_v8931 = "// Вид 2 — шейдер экрана (screen_shader): функция (io, кадр, глубина), в пачке фигура m = 8 — x0 номер записи, x1 шейдер;\n"; *(const char * *)tb_grow(v_lines) = tb_v8931; }
    { const char * tb_v8932 = "// вид 3 — вершины для экрана (один треугольник на всё окно). sv — настройки шейдера экрана (screen_set)\n"; *(const char * *)tb_grow(v_lines) = tb_v8932; }
    { const char * tb_v8933 = "typedef void (*tb_scrfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io, const uint32_t *scr, const float *scz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8933; }
    { const char * tb_v8934 = "typedef struct { const char *name; int stage; tb_shfn fn; const uint32_t *spv; size_t bytes; int nsets; char sets[8][32]; float sv[8]; } tb_shader_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8934; }
    { const char * tb_v8935 = "enum { TB_SH_MAX = 64, TB_SHR_CAP = 4096, TB_SHR_N = 224, TB_SHB_CAP = 12 * 32768 };   // TB_SHB_CAP — числа матриц костей на набор\n"; *(const char * *)tb_grow(v_lines) = tb_v8935; }
    { const char * tb_v8936 = "TB_API tb_shader_t tb_shaders[TB_SH_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v8936; }
    { const char * tb_v8937 = "TB_API int tb_nshaders = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8937; }
    { const char * tb_v8938 = "TB_API const char *tb_sh_msl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8938; }
    { const char * tb_v8939 = "TB_API float *tb_shrecs = 0;          // записи текущего набора: TB_SHR_N чисел на draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8939; }
    { const char * tb_v8940 = "TB_API int tb_shrn = 0;            // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8940; }
    { const char * tb_v8941 = "TB_API float *tb_shbones = 0;      // матрицы костей текущего набора (после всех записей в том же буфере)\n"; *(const char * *)tb_grow(v_lines) = tb_v8941; }
    { const char * tb_v8942 = "TB_API long long tb_shbn = 0, tb_shbase = 0;   // сколько чисел занято; где они начинаются в буфере (номер числа)\n"; *(const char * *)tb_grow(v_lines) = tb_v8942; }
    { const char * tb_v8943 = "#define TB_SHB_AT(map) do { tb_shbase = (long long)TB_SHR_N * TB_SHR_CAP * TB_GSLOTS + (long long)tb_gslot * TB_SHB_CAP; tb_shbones = (map) + tb_shbase; tb_shbn = 0; } while (0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8943; }
    { const char * tb_v8944 = "TB_API int tb_sh_frame = 0;        // в кадре была сетка со своим шейдером: TB_GPU_CHECK кадр не сверяет\n"; *(const char * *)tb_grow(v_lines) = tb_v8944; }
    { const char * tb_v8945 = "TB_API void tb_sh_lib(const char *msl) { tb_sh_msl = msl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8945; }
    { const char * tb_v8946 = "TB_API void tb_sh_reg(const char *name, int stage, tb_shfn fn, const uint32_t *spv, size_t bytes, const char *sets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8946; }
    { const char * tb_v8947 = "    if (tb_nshaders == TB_SH_MAX) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8947; }
    { const char * tb_v8948 = "    tb_shader_t *s = &tb_shaders[tb_nshaders++];\n"; *(const char * *)tb_grow(v_lines) = tb_v8948; }
