    { const char * tb_v8998 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v8998; }
