    { const char * tb_v9031 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9031; }
    { const char * tb_v9032 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9032; }
