    { const char * tb_v9035 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v9035; }
    { const char * tb_v9036 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9036; }
    { const char * tb_v9037 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9037; }
