    { const char * tb_v11426 = "        if (sz > 32 && sz < (64 << 20)) { data = malloc((size_t)sz); if (data && fread(data, 1, (size_t)sz, fl) == (size_t)sz) len = (size_t)sz; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11426; }
