    { const char * tb_v12245 = "// ---------- экран и мышь в ядре (tb bare) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v12245; }
    { const char * tb_v12246 = "// Экран: видеокарта Bochs/QEMU (BGA, «-vga std»): режим w×h, 32 бита на точку, буфер кадра в памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v12246; }
    { const char * tb_v12247 = "// Где буфер — говорит шина PCI (BAR0). Кадр рисуется в tb_px, на экран копируется целиком.\n"; *(const char * *)tb_grow(v_lines) = tb_v12247; }
    { const char * tb_v12248 = "// Мышь PS/2 (прерывание 12), клавиатура — та же, что для read_key.\n"; *(const char * *)tb_grow(v_lines) = tb_v12248; }
    { const char * tb_v12249 = "TB_API volatile uint32_t *tb_lfb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12249; }
    { const char * tb_v12250 = "TB_API int tb_bcur = 0;          // курсор: 0 стрелка ... 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v12250; }
    { const char * tb_v12251 = "TB_API char *tb_bclip = 0;       // буфер обмена — просто текст в памяти ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v12251; }
    { const char * tb_v12252 = "TB_API unsigned tb_pci_r(int bus, int dev, int fn, int off) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12252; }
    { const char * tb_v12253 = "    tb_outl(0xCF8, 0x80000000u | (unsigned)bus << 16 | (unsigned)dev << 11 | (unsigned)fn << 8 | (unsigned)(off & 0xFC));\n"; *(const char * *)tb_grow(v_lines) = tb_v12253; }
    { const char * tb_v12254 = "    return tb_inl(0xCFC);\n"; *(const char * *)tb_grow(v_lines) = tb_v12254; }
