    { const char * tb_v12265 = "TB_API unsigned short tb_bga_r(unsigned short i) { tb_outw(0x1CE, i); return tb_inw(0x1CF); }\n"; *(const char * *)tb_grow(v_lines) = tb_v12265; }
    { const char * tb_v12266 = "// окно устройства в страницы (по 2 МБ, писать можно, без кэша чтения)\n"; *(const char * *)tb_grow(v_lines) = tb_v12266; }
