    { const char * tb_v12274 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12274; }
    { const char * tb_v12275 = "// --- клавиши для key_down / typed_text (набор 1, как шлёт контроллер клавиатуры) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v12275; }
    { const char * tb_v12276 = "TB_API int tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12276; }
