    { const char * tb_v12282 = "        case 0x49: return TB_K_PGUP; case 0x51: return TB_K_PGDN; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v12282; }
    { const char * tb_v12283 = "        case 0x1C: return TB_K_ENTER;\n"; *(const char * *)tb_grow(v_lines) = tb_v12283; }
    { const char * tb_v12284 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12284; }
    { const char * tb_v12285 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12285; }
    { const char * tb_v12286 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12286; }
    { const char * tb_v12287 = "    switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12287; }
    { const char * tb_v12288 = "    case 0x1C: return TB_K_ENTER; case 0x01: return TB_K_ESC; case 0x39: return TB_K_SPACE; case 0x0E: return TB_K_BACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v12288; }
    { const char * tb_v12289 = "    case 0x0F: return TB_K_TAB; case 0x2A: case 0x36: return TB_K_SHIFT; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v12289; }
    { const char * tb_v12290 = "    case 0x57: return TB_K_F1 + 10; case 0x58: return TB_K_F1 + 11;\n"; *(const char * *)tb_grow(v_lines) = tb_v12290; }
    { const char * tb_v12291 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12291; }
    { const char * tb_v12292 = "    if (sc >= 0x3B && sc <= 0x44) return TB_K_F1 + (sc - 0x3B);\n"; *(const char * *)tb_grow(v_lines) = tb_v12292; }
    { const char * tb_v12293 = "    if (sc < 58) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12293; }
