    { const char * tb_v12297 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12297; }
    { const char * tb_v12298 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12298; }
    { const char * tb_v12299 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12299; }
    { const char * tb_v12300 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12300; }
    { const char * tb_v12301 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12301; }
    { const char * tb_v12302 = "    int up = sc & 0x80, ext = tb_kext;\n"; *(const char * *)tb_grow(v_lines) = tb_v12302; }
