    { const char * tb_v12304 = "    sc &= 0x7F;\n"; *(const char * *)tb_grow(v_lines) = tb_v12304; }
    { const char * tb_v12305 = "    int k = tb_sc_key(sc, ext);\n"; *(const char * *)tb_grow(v_lines) = tb_v12305; }
    { const char * tb_v12306 = "    if (k) { tb_keys[k] = !up; if (!up) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12306; }
    { const char * tb_v12307 = "    if (!up && !ext && sc < 58 && !tb_keys[TB_K_CTRL]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12307; }
