    { const char * tb_v12311 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12311; }
    { const char * tb_v12312 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v12312; }
    { const char * tb_v12313 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v12313; }
    { const char * tb_v12314 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v12314; }
    { const char * tb_v12315 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v12315; }
    { const char * tb_v12316 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12316; }
    { const char * tb_v12317 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v12317; }
    { const char * tb_v12318 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12318; }
    { const char * tb_v12319 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12319; }
    { const char * tb_v12320 = "TB_API int tb_mouse_cmd(unsigned char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12320; }
    { const char * tb_v12321 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xD4);\n"; *(const char * *)tb_grow(v_lines) = tb_v12321; }
