    { const char * tb_v12324 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12324; }
    { const char * tb_v12325 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v12325; }
    { const char * tb_v12326 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v12326; }
    { const char * tb_v12327 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12327; }
