    { const char * tb_v12335 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v12335; }
    { const char * tb_v12336 = "    if (r[1] != 0x564D5868u) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v12336; }
