    { const char * tb_v12342 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v12342; }
    { const char * tb_v12343 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12343; }
