    { const char * tb_v12352 = "        tb_mx = (int)((uint64_t)r[1] * (uint64_t)tb_gw / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v12352; }
    { const char * tb_v12353 = "        tb_my = (int)((uint64_t)r[2] * (uint64_t)tb_gh / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v12353; }
    { const char * tb_v12354 = "        int down = (r[0] & 0x20) != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12354; }
    { const char * tb_v12355 = "        if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12355; }
    { const char * tb_v12356 = "        tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v12356; }
