    { const char * tb_v12360 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12360; }
    { const char * tb_v12361 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12361; }
    { const char * tb_v12362 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v12362; }
    { const char * tb_v12363 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v12363; }
