    { const char * tb_v12366 = "    if (tb_vmm) { tb_vmm_read(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12366; }
    { const char * tb_v12367 = "    if (tb_mpn == 0 && !(b & 8)) return;           // первый байт пакета всегда с битом 3\n"; *(const char * *)tb_grow(v_lines) = tb_v12367; }
