    { const char * tb_v14212 = "        else if (e.type == UnmapNotify) tb_hidden = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14212; }
    { const char * tb_v14213 = "        else if (e.type == MapNotify) tb_hidden = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14213; }
    { const char * tb_v14214 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14214; }
    { const char * tb_v14215 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v14215; }
    { const char * tb_v14216 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14216; }
    { const char * tb_v14217 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14217; }
    { const char * tb_v14218 = "    if (tb_wcur != was) tb_wswitch(was);\n"; *(const char * *)tb_grow(v_lines) = tb_v14218; }
    { const char * tb_v14219 = "    if (tb_mlock && tb_mwarp) { XWarpPointer(tb_dpy, None, tb_xw, 0, 0, 0, 0, tb_gw / 2, tb_gh / 2); tb_mwarp = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14219; }
    { const char * tb_v14220 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v14220; }
    { const char * tb_v14221 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14221; }
    { const char * tb_v14222 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v14222; }
    { const char * tb_v14223 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v14223; }
    { const char * tb_v14224 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v14224; }
    { const char * tb_v14225 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v14225; }
    { const char * tb_v14226 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v14226; }
    { const char * tb_v14227 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v14227; }
    { const char * tb_v14228 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14228; }
    { const char * tb_v14229 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14229; }
    { const char * tb_v14230 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14230; }
    { const char * tb_v14231 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14231; }
    { const char * tb_v14232 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14232; }
    { const char * tb_v14233 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v14233; }
    { const char * tb_v14234 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14234; }
    { const char * tb_v14235 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v14235; }
    { const char * tb_v14236 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v14236; }
    { const char * tb_v14237 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v14237; }
    { const char * tb_v14238 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14238; }
    { const char * tb_v14239 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14239; }
    { const char * tb_v14240 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v14240; }
    { const char * tb_v14241 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v14241; }
    { const char * tb_v14242 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v14242; }
    { const char * tb_v14243 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14243; }
    { const char * tb_v14244 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14244; }
    { const char * tb_v14245 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14245; }
    { const char * tb_v14246 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14246; }
    { const char * tb_v14247 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14247; }
    { const char * tb_v14248 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14248; }
    { const char * tb_v14249 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14249; }
    { const char * tb_v14250 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v14250; }
    { const char * tb_v14251 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v14251; }
    { const char * tb_v14252 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14252; }
    { const char * tb_v14253 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14253; }
    { const char * tb_v14254 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14254; }
    { const char * tb_v14255 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14255; }
    { const char * tb_v14256 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14256; }
    { const char * tb_v14257 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14257; }
    { const char * tb_v14258 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14258; }
    { const char * tb_v14259 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14259; }
    { const char * tb_v14260 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14260; }
    { const char * tb_v14261 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14261; }
    { const char * tb_v14262 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14262; }
    { const char * tb_v14263 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14263; }
    { const char * tb_v14264 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14264; }
    { const char * tb_v14265 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v14265; }
    { const char * tb_v14266 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14266; }
    { const char * tb_v14267 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v14267; }
    { const char * tb_v14268 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v14268; }
    { const char * tb_v14269 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14269; }
    { const char * tb_v14270 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14270; }
    { const char * tb_v14271 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14271; }
    { const char * tb_v14272 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14272; }
    { const char * tb_v14273 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v14273; }
    { const char * tb_v14274 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14274; }
    { const char * tb_v14275 = "        fprintf(stderr, tb_tr(\"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\"), diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14275; }
    { const char * tb_v14276 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14276; }
    { const char * tb_v14277 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14277; }
    { const char * tb_v14278 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v14278; }
    { const char * tb_v14279 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v14279; }
    { const char * tb_v14280 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v14280; }
    { const char * tb_v14281 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14281; }
    { const char * tb_v14282 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14282; }
    { const char * tb_v14283 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14283; }
    { const char * tb_v14284 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v14284; }
    { const char * tb_v14285 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v14285; }
    { const char * tb_v14286 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v14286; }
    { const char * tb_v14287 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v14287; }
    { const char * tb_v14288 = "    int used;\n"; *(const char * *)tb_grow(v_lines) = tb_v14288; }
    { const char * tb_v14289 = "    uint32_t *px; int gw, gh, gclosed, mx, my, mdown, mtap, wheel; double wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v14289; }
    { const char * tb_v14290 = "    int mside[2], mside_tap[2], ntyped; char typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v14290; }
    { const char * tb_v14291 = "    unsigned char keys[256], ktap[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v14291; }
    { const char * tb_v14292 = "    int new_w, new_h, resizable, gpu_on, zclr, gzclr; uint32_t *zb; long long zb_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14292; }
    { const char * tb_v14293 = "    TB_WPLAT\n"; *(const char * *)tb_grow(v_lines) = tb_v14293; }
    { const char * tb_v14294 = "} tb_wslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v14294; }
    { const char * tb_v14295 = "static tb_wslot tb_wins[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v14295; }
    { const char * tb_v14296 = "#define TB_WFIELDS(X) X(px, tb_px) X(gw, tb_gw) X(gh, tb_gh) X(gclosed, tb_gclosed) X(mx, tb_mx) X(my, tb_my) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v14296; }
    { const char * tb_v14297 = "    X(mdown, tb_mdown) X(mtap, tb_mtap) X(wheel, tb_wheel) X(wheel_f, tb_wheel_f) X(ntyped, tb_ntyped) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v14297; }
    { const char * tb_v14298 = "    X(new_w, tb_new_w) X(new_h, tb_new_h) X(resizable, tb_resizable) X(gpu_on, tb_gpu_on) X(zclr, tb_zclr) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v14298; }
    { const char * tb_v14299 = "    X(gzclr, tb_gzclr) X(zb, tb_zb) X(zb_n, tb_zb_n)\n"; *(const char * *)tb_grow(v_lines) = tb_v14299; }
    { const char * tb_v14300 = "#define TB_WSAVE1(f, g) s->f = g;\n"; *(const char * *)tb_grow(v_lines) = tb_v14300; }
    { const char * tb_v14301 = "#define TB_WLOAD1(f, g) g = s->f;\n"; *(const char * *)tb_grow(v_lines) = tb_v14301; }
    { const char * tb_v14302 = "static void tb_wsave(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14302; }
    { const char * tb_v14303 = "    TB_WFIELDS(TB_WSAVE1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14303; }
    { const char * tb_v14304 = "    memcpy(s->mside, tb_mside, sizeof s->mside); memcpy(s->mside_tap, tb_mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14304; }
    { const char * tb_v14305 = "    memcpy(s->typed, tb_typed, sizeof s->typed); memcpy(s->keys, tb_keys, sizeof s->keys); memcpy(s->ktap, tb_ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14305; }
    { const char * tb_v14306 = "    TB_WPLAT_SAVE(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v14306; }
    { const char * tb_v14307 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14307; }
    { const char * tb_v14308 = "static void tb_wload(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14308; }
    { const char * tb_v14309 = "    TB_WFIELDS(TB_WLOAD1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14309; }
    { const char * tb_v14310 = "    memcpy(tb_mside, s->mside, sizeof s->mside); memcpy(tb_mside_tap, s->mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14310; }
    { const char * tb_v14311 = "    memcpy(tb_typed, s->typed, sizeof s->typed); memcpy(tb_keys, s->keys, sizeof s->keys); memcpy(tb_ktap, s->ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14311; }
    { const char * tb_v14312 = "    TB_WPLAT_LOAD(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v14312; }
    { const char * tb_v14313 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14313; }
    { const char * tb_v14314 = "TB_API int tb_wfind(uintptr_t h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14314; }
    { const char * tb_v14315 = "    for (int i = 0; i < tb_wn; i++) if (tb_wins[i].used && tb_whand[i] == h && h) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v14315; }
    { const char * tb_v14316 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14316; }
    { const char * tb_v14317 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14317; }
    { const char * tb_v14318 = "// сделать окно i текущим: 3D, которое ждало, дорисовывается в прежнее окно\n"; *(const char * *)tb_grow(v_lines) = tb_v14318; }
    { const char * tb_v14319 = "TB_API void tb_wswitch(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14319; }
    { const char * tb_v14320 = "    if (i == tb_wcur || i < 0 || i >= tb_wn || !tb_wins[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14320; }
    { const char * tb_v14321 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14321; }
    { const char * tb_v14322 = "    tb_wsave(&tb_wins[tb_wcur]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14322; }
    { const char * tb_v14323 = "    tb_wload(&tb_wins[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14323; }
    { const char * tb_v14324 = "    tb_wcur = i;\n"; *(const char * *)tb_grow(v_lines) = tb_v14324; }
    { const char * tb_v14325 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14325; }
    { const char * tb_v14326 = "TB_API void tb_wmark_closed(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14326; }
    { const char * tb_v14327 = "    if (i == tb_wcur) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14327; }
    { const char * tb_v14328 = "    else if (i >= 0 && i < tb_wn) tb_wins[i].gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14328; }
    { const char * tb_v14329 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14329; }
    { const char * tb_v14330 = "TB_API int tb_gfx_open2(const char *title);\n"; *(const char * *)tb_grow(v_lines) = tb_v14330; }
    { const char * tb_v14331 = "TB_API void tb_gfx_show(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v14331; }
    { const char * tb_v14332 = "TB_API void tb_gfx_close2(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v14332; }
    { const char * tb_v14333 = "TB_API void tb_gfx_poll(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v14333; }
    { const char * tb_v14334 = "TB_API long long tb_window_new(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14334; }
    { const char * tb_v14335 = "    if (tb_wn == 0) { tb_err = \"сначала открой главное окно: window_open\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14335; }
    { const char * tb_v14336 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14336; }
    { const char * tb_v14337 = "    int i = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14337; }
    { const char * tb_v14338 = "    while (i < tb_wn && tb_wins[i].used) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14338; }
    { const char * tb_v14339 = "    if (i >= TB_WMAX) { tb_err = \"окон больше 16 не бывает\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14339; }
    { const char * tb_v14340 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14340; }
    { const char * tb_v14341 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v14341; }
    { const char * tb_v14342 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v14342; }
    { const char * tb_v14343 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v14343; }
    { const char * tb_v14344 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14344; }
