    { const char * tb_v14557 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14557; }
    { const char * tb_v14558 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb).\n"; *(const char * *)tb_grow(v_lines) = tb_v14558; }
    { const char * tb_v14559 = "// Смешивание как у видеокарты: округл(цвет * a / 255) + округл(фон * (255 - a) / 255), a = 255 − прозрачность;\n"; *(const char * *)tb_grow(v_lines) = tb_v14559; }
    { const char * tb_v14560 = "// в TB_GPU_CHECK — по таблице пробы (tb_blend_lut), тогда кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14560; }
    { const char * tb_v14561 = "TB_INL uint32_t tb_mix_a(uint32_t d, uint32_t c, uint32_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14561; }
    { const char * tb_v14562 = "    if (a >= 255) return c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14562; }
    { const char * tb_v14563 = "    if (a == 0) return d & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14563; }
    { const char * tb_v14564 = "    uint32_t r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14564; }
    { const char * tb_v14565 = "    for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14565; }
    { const char * tb_v14566 = "        uint32_t sc = (c >> sh) & 255, dc = (d >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14566; }
    { const char * tb_v14567 = "        uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14567; }
    { const char * tb_v14568 = "        r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14568; }
    { const char * tb_v14569 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14569; }
    { const char * tb_v14570 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14570; }
    { const char * tb_v14571 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14571; }
    { const char * tb_v14572 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14572; }
    { const char * tb_v14573 = "    return tb_mix_a(d, c, 255 - ((c >> 24) & 255));\n"; *(const char * *)tb_grow(v_lines) = tb_v14573; }
    { const char * tb_v14574 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14574; }
    { const char * tb_v14575 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14575; }
    { const char * tb_v14576 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14576; }
    { const char * tb_v14577 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14577; }
    { const char * tb_v14578 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14578; }
    { const char * tb_v14579 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14579; }
    { const char * tb_v14580 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14580; }
    { const char * tb_v14581 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14581; }
    { const char * tb_v14582 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14582; }
    { const char * tb_v14583 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14583; }
    { const char * tb_v14584 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14584; }
    { const char * tb_v14585 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14585; }
    { const char * tb_v14586 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14586; }
