    { const char * tb_v14588 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14588; }
    { const char * tb_v14589 = "// точка (i, j) с прозрачностью a (0..255) цвета c\n"; *(const char * *)tb_grow(v_lines) = tb_v14589; }
    { const char * tb_v14590 = "TB_INL void tb_put_a(long long i, long long j, uint32_t c, uint32_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14590; }
    { const char * tb_v14591 = "    if (i < 0 || j < 0 || i >= tb_gw || j >= tb_gh || a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14591; }
    { const char * tb_v14592 = "    uint32_t *p = &tb_px[j * tb_gw + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14592; }
    { const char * tb_v14593 = "    *p = tb_mix_a(*p, c, a);\n"; *(const char * *)tb_grow(v_lines) = tb_v14593; }
    { const char * tb_v14594 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14594; }
    { const char * tb_v14595 = "// целый корень floor(sqrt(n)) — одинаково на процессоре и в шейдере\n"; *(const char * *)tb_grow(v_lines) = tb_v14595; }
    { const char * tb_v14596 = "TB_INL uint32_t tb_isqrt(uint32_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14596; }
    { const char * tb_v14597 = "    uint32_t s = (uint32_t)sqrt((double)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v14597; }
    { const char * tb_v14598 = "    while (s * s > n) s--;\n"; *(const char * *)tb_grow(v_lines) = tb_v14598; }
    { const char * tb_v14599 = "    while ((s + 1) * (s + 1) <= n) s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14599; }
    { const char * tb_v14600 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14600; }
    { const char * tb_v14601 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14601; }
    { const char * tb_v14602 = "// сглаженный угол: q = (2·dx)² + (2·dy)² от центра угла до середины точки, радиус r ≤ 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v14602; }
    { const char * tb_v14603 = "// Покрытие 0..255 = (r + 0.5 − расстояние), целыми числами (так же считает шейдер)\n"; *(const char * *)tb_grow(v_lines) = tb_v14603; }
    { const char * tb_v14604 = "TB_INL uint32_t tb_round_cov(uint32_t q, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14604; }
    { const char * tb_v14605 = "    long long lo = 2 * r - 1, hi = 2 * r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14605; }
    { const char * tb_v14606 = "    if (lo >= 0 && q <= (uint32_t)(lo * lo)) return 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14606; }
    { const char * tb_v14607 = "    if (q >= (uint32_t)(hi * hi)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14607; }
    { const char * tb_v14608 = "    long long v = (2 * r + 1) * 64 - (long long)tb_isqrt(q * 4096u);   // 128 · (r + 0.5 − расстояние)\n"; *(const char * *)tb_grow(v_lines) = tb_v14608; }
    { const char * tb_v14609 = "    if (v < 0) v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14609; }
    { const char * tb_v14610 = "    v = (v * 255 + 64) / 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v14610; }
    { const char * tb_v14611 = "    return v > 255 ? 255 : (uint32_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14611; }
    { const char * tb_v14612 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14612; }
    { const char * tb_v14613 = "// тень: внутри радиуса r — вся (ca), дальше к r + size сходит на нет по квадрату; r + size ≤ 255\n"; *(const char * *)tb_grow(v_lines) = tb_v14613; }
    { const char * tb_v14614 = "TB_INL uint32_t tb_shadow_a(uint32_t q, long long r, long long size, uint32_t ca) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14614; }
    { const char * tb_v14615 = "    if (q <= (uint32_t)(4 * r * r)) return ca;\n"; *(const char * *)tb_grow(v_lines) = tb_v14615; }
    { const char * tb_v14616 = "    if (q >= (uint32_t)(4 * (r + size) * (r + size))) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14616; }
    { const char * tb_v14617 = "    long long g = ((r + size) * 128 - (long long)tb_isqrt(q * 4096u)) >> 3;   // осталось до края, в 1/16 точки\n"; *(const char * *)tb_grow(v_lines) = tb_v14617; }
    { const char * tb_v14618 = "    uint32_t S = (uint32_t)(size * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14618; }
    { const char * tb_v14619 = "    if (g < 0) g = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14619; }
    { const char * tb_v14620 = "    if (g > (long long)S) g = S;\n"; *(const char * *)tb_grow(v_lines) = tb_v14620; }
    { const char * tb_v14621 = "    return (ca * (uint32_t)g * (uint32_t)g + S * S / 2) / (S * S);\n"; *(const char * *)tb_grow(v_lines) = tb_v14621; }
    { const char * tb_v14622 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14622; }
    { const char * tb_v14623 = "// угол-квадрат x0..x1, y0..y1 с центром (ox, oy): сглаженный (shadow = 0) или угол тени\n"; *(const char * *)tb_grow(v_lines) = tb_v14623; }
    { const char * tb_v14624 = "TB_API void tb_soft_corner(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, long long r, long long size, long long c, int shadow) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14624; }
    { const char * tb_v14625 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14625; }
    { const char * tb_v14626 = "    if (tb_gpu_on) tb_gpu_soft(x0, y0, x1, y1, ox, oy, c, shadow ? (1u << 28) | ((uint32_t)size << 11) | (uint32_t)r : (1u << 29) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v14626; }
    { const char * tb_v14627 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14627; }
    { const char * tb_v14628 = "    uint32_t ca = 255 - (((uint32_t)c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14628; }
    { const char * tb_v14629 = "    long long ja = y0 < 0 ? 0 : y0, jb = y1 > tb_gh ? tb_gh : y1, ia = x0 < 0 ? 0 : x0, ib = x1 > tb_gw ? tb_gw : x1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14629; }
    { const char * tb_v14630 = "    for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14630; }
    { const char * tb_v14631 = "        long long dx = 2 * (i - ox) + 1, dy = 2 * (j - oy) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14631; }
    { const char * tb_v14632 = "        uint32_t q = (uint32_t)(dx * dx + dy * dy), a;\n"; *(const char * *)tb_grow(v_lines) = tb_v14632; }
    { const char * tb_v14633 = "        if (shadow) a = tb_shadow_a(q, r, size, ca);\n"; *(const char * *)tb_grow(v_lines) = tb_v14633; }
    { const char * tb_v14634 = "        else a = (tb_round_cov(q, r) * ca + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14634; }
    { const char * tb_v14635 = "        tb_put_a(i, j, (uint32_t)c, a);\n"; *(const char * *)tb_grow(v_lines) = tb_v14635; }
    { const char * tb_v14636 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14636; }
    { const char * tb_v14637 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14637; }
    { const char * tb_v14638 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v14638; }
    { const char * tb_v14639 = "// снаружи к size точкам сходит на нет. Точки делятся на куски без наложений: середина — сплошняком,\n"; *(const char * *)tb_grow(v_lines) = tb_v14639; }
    { const char * tb_v14640 = "// полосы вдоль сторон — по строке/столбцу одной прозрачности, углы — по кругу (tb_soft_corner).\n"; *(const char * *)tb_grow(v_lines) = tb_v14640; }
    { const char * tb_v14641 = "// Всё целыми числами, поэтому видеокарта рисует то же самое точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14641; }
    { const char * tb_v14642 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14642; }
    { const char * tb_v14643 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14643; }
    { const char * tb_v14644 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14644; }
    { const char * tb_v14645 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14645; }
    { const char * tb_v14646 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14646; }
    { const char * tb_v14647 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14647; }
    { const char * tb_v14648 = "    if (r > 127) r = 127;\n"; *(const char * *)tb_grow(v_lines) = tb_v14648; }
    { const char * tb_v14649 = "    if (size > 255 - r) size = 255 - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14649; }
    { const char * tb_v14650 = "    uint32_t ca = 255 - (((uint32_t)c >> 24) & 255), rgb = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14650; }
    { const char * tb_v14651 = "    // середина\n"; *(const char * *)tb_grow(v_lines) = tb_v14651; }
    { const char * tb_v14652 = "    tb_draw_rect(x, y + r, w, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14652; }
    { const char * tb_v14653 = "    tb_draw_rect(x + r, y, w - 2 * r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14653; }
    { const char * tb_v14654 = "    tb_draw_rect(x + r, y + h - r, w - 2 * r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14654; }
    { const char * tb_v14655 = "    // полосы вдоль сторон: k-я строка/столбец от края\n"; *(const char * *)tb_grow(v_lines) = tb_v14655; }
    { const char * tb_v14656 = "    for (long long k = 0; k < size; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14656; }
    { const char * tb_v14657 = "        uint32_t q = (uint32_t)((2 * k + 1) * (2 * k + 1)), a = tb_shadow_a(q, 0, size, ca);\n"; *(const char * *)tb_grow(v_lines) = tb_v14657; }
    { const char * tb_v14658 = "        if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v14658; }
    { const char * tb_v14659 = "        long long cc = (long long)(((255 - a) << 24) | rgb);\n"; *(const char * *)tb_grow(v_lines) = tb_v14659; }
    { const char * tb_v14660 = "        tb_draw_rect(x + r, y - 1 - k, w - 2 * r, 1, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14660; }
    { const char * tb_v14661 = "        tb_draw_rect(x + r, y + h + k, w - 2 * r, 1, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14661; }
    { const char * tb_v14662 = "        tb_draw_rect(x - 1 - k, y + r, 1, h - 2 * r, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14662; }
    { const char * tb_v14663 = "        tb_draw_rect(x + w + k, y + r, 1, h - 2 * r, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14663; }
    { const char * tb_v14664 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14664; }
    { const char * tb_v14665 = "    // углы\n"; *(const char * *)tb_grow(v_lines) = tb_v14665; }
    { const char * tb_v14666 = "    tb_soft_corner(x - size, y - size, x + r, y + r, x + r, y + r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14666; }
    { const char * tb_v14667 = "    tb_soft_corner(x + w - r, y - size, x + w + size, y + r, x + w - r, y + r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14667; }
    { const char * tb_v14668 = "    tb_soft_corner(x - size, y + h - r, x + r, y + h + size, x + r, y + h - r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14668; }
    { const char * tb_v14669 = "    tb_soft_corner(x + w - r, y + h - r, x + w + size, y + h + size, x + w - r, y + h - r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14669; }
    { const char * tb_v14670 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14670; }
    { const char * tb_v14671 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v14671; }
    { const char * tb_v14672 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14672; }
    { const char * tb_v14673 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14673; }
    { const char * tb_v14674 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14674; }
    { const char * tb_v14675 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v14675; }
    { const char * tb_v14676 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v14676; }
    { const char * tb_v14677 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14677; }
    { const char * tb_v14678 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14678; }
    { const char * tb_v14679 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14679; }
    { const char * tb_v14680 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14680; }
    { const char * tb_v14681 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14681; }
    { const char * tb_v14682 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14682; }
    { const char * tb_v14683 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v14683; }
    { const char * tb_v14684 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14684; }
    { const char * tb_v14685 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v14685; }
    { const char * tb_v14686 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14686; }
    { const char * tb_v14687 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba).\n"; *(const char * *)tb_grow(v_lines) = tb_v14687; }
    { const char * tb_v14688 = "// Куски без наложений: середина и боковые полосы — прямоугольники, углы — сглаженные квадраты r×r\n"; *(const char * *)tb_grow(v_lines) = tb_v14688; }
    { const char * tb_v14689 = "// (tb_soft_corner): процессор и видеокарта считают покрытие одной целой формулой\n"; *(const char * *)tb_grow(v_lines) = tb_v14689; }
    { const char * tb_v14690 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14690; }
    { const char * tb_v14691 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14691; }
    { const char * tb_v14692 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14692; }
    { const char * tb_v14693 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v14693; }
    { const char * tb_v14694 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14694; }
    { const char * tb_v14695 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14695; }
    { const char * tb_v14696 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14696; }
    { const char * tb_v14697 = "    if (r > 255) r = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14697; }
    { const char * tb_v14698 = "    if (r == 0) { tb_draw_rect(x, y, w, h, c); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14698; }
    { const char * tb_v14699 = "    tb_draw_rect(x + r, y, w - 2 * r, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14699; }
    { const char * tb_v14700 = "    tb_draw_rect(x, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14700; }
    { const char * tb_v14701 = "    tb_draw_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14701; }
    { const char * tb_v14702 = "    long long cx[4] = { x, x + w - r, x, x + w - r }, cy[4] = { y, y, y + h - r, y + h - r };\n"; *(const char * *)tb_grow(v_lines) = tb_v14702; }
    { const char * tb_v14703 = "    long long ox[4] = { x + r, x + w - r, x + r, x + w - r }, oy[4] = { y + r, y + r, y + h - r, y + h - r };\n"; *(const char * *)tb_grow(v_lines) = tb_v14703; }
    { const char * tb_v14704 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14704; }
    { const char * tb_v14705 = "        if (m & (1 << k)) tb_soft_corner(cx[k], cy[k], cx[k] + r, cy[k] + r, ox[k], oy[k], r, 0, c, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14705; }
    { const char * tb_v14706 = "        else tb_draw_rect(cx[k], cy[k], r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14706; }
    { const char * tb_v14707 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14707; }
    { const char * tb_v14708 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14708; }
    { const char * tb_v14709 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v14709; }
    { const char * tb_v14710 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14710; }
    { const char * tb_v14711 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14711; }
    { const char * tb_v14712 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v14712; }
    { const char * tb_v14713 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14713; }
    { const char * tb_v14714 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v14714; }
    { const char * tb_v14715 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14715; }
    { const char * tb_v14716 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v14716; }
    { const char * tb_v14717 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14717; }
    { const char * tb_v14718 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14718; }
    { const char * tb_v14719 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14719; }
    { const char * tb_v14720 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v14720; }
    { const char * tb_v14721 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v14721; }
    { const char * tb_v14722 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14722; }
    { const char * tb_v14723 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14723; }
    { const char * tb_v14724 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14724; }
    { const char * tb_v14725 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14725; }
    { const char * tb_v14726 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14726; }
    { const char * tb_v14727 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14727; }
    { const char * tb_v14728 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v14728; }
    { const char * tb_v14729 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v14729; }
    { const char * tb_v14730 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14730; }
    { const char * tb_v14731 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14731; }
    { const char * tb_v14732 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14732; }
    { const char * tb_v14733 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14733; }
    { const char * tb_v14734 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14734; }
    { const char * tb_v14735 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14735; }
    { const char * tb_v14736 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14736; }
    { const char * tb_v14737 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14737; }
    { const char * tb_v14738 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14738; }
    { const char * tb_v14739 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14739; }
    { const char * tb_v14740 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14740; }
    { const char * tb_v14741 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v14741; }
    { const char * tb_v14742 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14742; }
    { const char * tb_v14743 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14743; }
    { const char * tb_v14744 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14744; }
