    { const char * tb_v14827 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14827; }
    { const char * tb_v14828 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14828; }
    { const char * tb_v14829 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v14829; }
