    { const char * tb_v14841 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v14841; }
    { const char * tb_v14842 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v14842; }
    { const char * tb_v14843 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14843; }
    { const char * tb_v14844 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14844; }
    { const char * tb_v14845 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14845; }
    { const char * tb_v14846 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v14846; }
    { const char * tb_v14847 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14847; }
    { const char * tb_v14848 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14848; }
    { const char * tb_v14849 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14849; }
    { const char * tb_v14850 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v14850; }
    { const char * tb_v14851 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14851; }
    { const char * tb_v14852 = "    *out = tb_imgpx[tx->off + (uint32_t)v * tx->w + (uint32_t)u];\n"; *(const char * *)tb_grow(v_lines) = tb_v14852; }
    { const char * tb_v14853 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v14853; }
    { const char * tb_v14854 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14854; }
    { const char * tb_v14855 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v14855; }
    { const char * tb_v14856 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14856; }
    { const char * tb_v14857 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v14857; }
    { const char * tb_v14858 = "             b = ((t & 255) * (c & 255) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14858; }
    { const char * tb_v14859 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14859; }
    { const char * tb_v14860 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14860; }
    { const char * tb_v14861 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14861; }
    { const char * tb_v14862 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14862; }
    { const char * tb_v14863 = "    const tb_gtex_t *tx = pl ? tb_tex_cur : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14863; }
    { const char * tb_v14864 = "    if (gpu) { if (tx) tb_gpu_tri3t(t, c, pl, tx); else if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14864; }
    { const char * tb_v14865 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14865; }
    { const char * tb_v14866 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14866; }
