    { const char * tb_v15016 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v15016; }
    { const char * tb_v15017 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v15017; }
