    { const char * tb_v15243 = "// ---- картинка на сетке: плоскости u·W и v·W по трём углам ----\n"; *(const char * *)tb_grow(v_lines) = tb_v15243; }
    { const char * tb_v15244 = "// треугольник t сетки рисуется картинкой? (есть картинка, у треугольника есть (u, v), видеокарта умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v15244; }
