    { const char * tb_v15439 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15439; }
    { const char * tb_v15440 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v15440; }
