    { const char * tb_v15444 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15444; }
    { const char * tb_v15445 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15445; }
    { const char * tb_v15446 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v15446; }
