    { const char * tb_v16285 = "    for (int q = 0; q < 3; q++) { e1[q] = p[1].c[q] - p[0].c[q]; e2[q] = p[2].c[q] - p[0].c[q]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16285; }
    { const char * tb_v16286 = "    double tri = p[0].c[0] * (e1[1] * e2[2] - e1[2] * e2[1]) + p[0].c[1] * (e1[2] * e2[0] - e1[0] * e2[2]) + p[0].c[2] * (e1[0] * e2[1] - e1[1] * e2[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16286; }
    { const char * tb_v16287 = "    int front = tri < 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16287; }
    { const char * tb_v16288 = "    if (cull < 0 && !front) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16288; }
