    { const char * tb_v16293 = "        if (!front) { n[0] = -n[0]; n[1] = -n[1]; n[2] = -n[2]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16293; }
    { const char * tb_v16294 = "        long long o[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v16294; }
