    { const char * tb_v16296 = "        for (int k = 0; k < 8; k++) p[i].a[k] = (double)o[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16296; }
    { const char * tb_v16297 = "        if (shadow) { long long s3[3]; tb_sm_corner(w, n, s3); p[i].a[8] = (double)s3[0]; p[i].a[9] = (double)s3[1]; p[i].a[10] = (double)s3[2]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16297; }
    { const char * tb_v16298 = "        else p[i].a[8] = p[i].a[9] = p[i].a[10] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16298; }
    { const char * tb_v16299 = "        p[i].a[11] = tex ? m->uv[6 * t + 2 * i] : 0; p[i].a[12] = tex ? m->uv[6 * t + 2 * i + 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16299; }
