    { const char * tb_v16303 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16303; }
    { const char * tb_v16304 = "// многоугольник веером на «новые» треугольники (рисует: только по порядку, на одном ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v16304; }
    { const char * tb_v16305 = "static void tb_lit_tri_put(const tb_srec *r, long long t, const tb_lv *p, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16305; }
