    { const char * tb_v16307 = "    tb_lctx cx = { m, t, m->c[t] & 0xFFFFFF, r->alpha, tb_tex_on(m, t), (tb_sm_live ? 1 : 0) | (tb_fog_on ? 2 : 0) };\n"; *(const char * *)tb_grow(v_lines) = tb_v16307; }
    { const char * tb_v16308 = "    for (int i = 1; i + 1 < n; i++) tb_lit_emit(&p[0], &p[i], &p[i + 1], &cx);\n"; *(const char * *)tb_grow(v_lines) = tb_v16308; }
