    { const char * tb_v16315 = "// ---- 1.4: свет и обрезка треугольников сцены на всех ядрах ----\n"; *(const char * *)tb_grow(v_lines) = tb_v16315; }
    { const char * tb_v16316 = "// Треугольники собираются в список работ по порядку; ядра считают кусками (tb_lit_tri_calc — только читает),\n"; *(const char * *)tb_grow(v_lines) = tb_v16316; }
    { const char * tb_v16317 = "// потом одно ядро рисует их в том же порядке. Кадр получается точка в точку тот же, что на одном ядре.\n"; *(const char * *)tb_grow(v_lines) = tb_v16317; }
    { const char * tb_v16318 = "typedef struct { const tb_srec *r; long long t; int cull; } tb_ljob;\n"; *(const char * *)tb_grow(v_lines) = tb_v16318; }
    { const char * tb_v16319 = "typedef struct { tb_lv p[12]; int n; } tb_lres;\n"; *(const char * *)tb_grow(v_lines) = tb_v16319; }
