    { const char * tb_v16321 = "static long long tb_lj_n = 0, tb_lj_cap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16321; }
    { const char * tb_v16322 = "static tb_lres *tb_lr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16322; }
    { const char * tb_v16323 = "static long long tb_lr_cap = 0, tb_lr_from = 0, tb_lr_to = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16323; }
    { const char * tb_v16324 = "static volatile long long tb_lr_next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16324; }
    { const char * tb_v16325 = "enum { TB_LBLOCK = 512, TB_LSTEP = 32 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16325; }
    { const char * tb_v16326 = "static void tb_lj_add(const tb_srec *r, long long t, int cull) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16326; }
    { const char * tb_v16327 = "    if (tb_lj_n == tb_lj_cap) { tb_lj_cap = tb_lj_cap ? tb_lj_cap * 2 : 4096; tb_lj = (tb_ljob *)realloc(tb_lj, sizeof(tb_ljob) * (size_t)tb_lj_cap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v16327; }
    { const char * tb_v16328 = "    tb_lj[tb_lj_n].r = r; tb_lj[tb_lj_n].t = t; tb_lj[tb_lj_n].cull = cull; tb_lj_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v16328; }
    { const char * tb_v16329 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16329; }
