    { const char * tb_v16331 = "    (void)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v16331; }
    { const char * tb_v16332 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16332; }
    { const char * tb_v16333 = "        long long a = __atomic_fetch_add(&tb_lr_next, TB_LSTEP, __ATOMIC_ACQ_REL) + tb_lr_from;\n"; *(const char * *)tb_grow(v_lines) = tb_v16333; }
    { const char * tb_v16334 = "        if (a >= tb_lr_to) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16334; }
    { const char * tb_v16335 = "        long long b = a + TB_LSTEP < tb_lr_to ? a + TB_LSTEP : tb_lr_to;\n"; *(const char * *)tb_grow(v_lines) = tb_v16335; }
    { const char * tb_v16336 = "        for (long long i = a; i < b; i++) tb_lr[i - tb_lr_from].n = tb_lit_tri_calc(tb_lj[i].r, tb_lj[i].t, tb_lj[i].cull, tb_lr[i - tb_lr_from].p);\n"; *(const char * *)tb_grow(v_lines) = tb_v16336; }
    { const char * tb_v16337 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16337; }
