    { const char * tb_v16339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16339; }
    { const char * tb_v16340 = "// Пока по желанию: TB_LIT_CORES=1 — свет и обрезку считают все ядра. На сервере с программной видеокартой (lavapipe)\n"; *(const char * *)tb_grow(v_lines) = tb_v16340; }
    { const char * tb_v16341 = "// выигрыша нет: она сама занимает все ядра, а рисование по порядку стоит половину; нужен замер на настоящей видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v16341; }
