    { const char * tb_v16347 = "// все собранные работы: посчитать (на всех ядрах) и нарисовать по порядку\n"; *(const char * *)tb_grow(v_lines) = tb_v16347; }
    { const char * tb_v16348 = "static void tb_lj_run(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16348; }
    { const char * tb_v16349 = "    if (!tb_lj_n) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v16349; }
    { const char * tb_v16350 = "    int cores = tb_lit_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v16350; }
