    { const char * tb_v16362 = "        for (long long i = from; i < tb_lr_to; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v16362; }
    { const char * tb_v16363 = "            if (tb_lr[i - from].n) tb_lit_tri_put(tb_lj[i].r, tb_lj[i].t, tb_lr[i - from].p, tb_lr[i - from].n);\n"; *(const char * *)tb_grow(v_lines) = tb_v16363; }
    { const char * tb_v16364 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16364; }
    { const char * tb_v16365 = "    tb_lj_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16365; }
    { const char * tb_v16366 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16366; }
    { const char * tb_v16367 = "// углы в мире для всех вызовов сцены — тоже на всех ядрах (нормали сеток считаются заранее, на одном)\n"; *(const char * *)tb_grow(v_lines) = tb_v16367; }
    { const char * tb_v16368 = "static volatile long long tb_lp_next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16368; }
    { const char * tb_v16369 = "static void *tb_lp_work(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16369; }
    { const char * tb_v16370 = "    (void)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v16370; }
    { const char * tb_v16371 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16371; }
