    { const char * tb_v16373 = "        if (i >= tb_nscene) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16373; }
    { const char * tb_v16374 = "        if (!tb_scene[i].sh) tb_lit_prepare(&tb_scene[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16374; }
    { const char * tb_v16375 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16375; }
