    { const char * tb_v16377 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16377; }
    { const char * tb_v16378 = "// весь вызов (непрозрачный): куски сетки, которые не видны, пропускаем (без костей — по шарам кусков)\n"; *(const char * *)tb_grow(v_lines) = tb_v16378; }
    { const char * tb_v16379 = "static void tb_lit_draw(tb_srec *r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16379; }
    { const char * tb_v16380 = "    tb_mesh *m = &tb_meshes[r->id];\n"; *(const char * *)tb_grow(v_lines) = tb_v16380; }
    { const char * tb_v16381 = "    int cull = r->alpha == 255 ? tb_mesh_cull(m) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16381; }
    { const char * tb_v16382 = "    if (r->bm) { for (long long t = 0; t < m->n; t++) tb_lj_add(r, t, cull); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16382; }
    { const char * tb_v16383 = "    double M[3][3], T[3], d[3] = { r->P[0] - tb_cam[0], r->P[1] - tb_cam[1], r->P[2] - tb_cam[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v16383; }
    { const char * tb_v16384 = "    for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16384; }
    { const char * tb_v16385 = "        const double *row = k == 0 ? tb_cam + 3 : k == 1 ? tb_cam + 6 : tb_camf;\n"; *(const char * *)tb_grow(v_lines) = tb_v16385; }
    { const char * tb_v16386 = "        for (int j = 0; j < 3; j++) M[k][j] = row[0] * r->R[0][j] + row[1] * r->R[1][j] + row[2] * r->R[2][j];\n"; *(const char * *)tb_grow(v_lines) = tb_v16386; }
    { const char * tb_v16387 = "        T[k] = row[0] * d[0] + row[1] * d[1] + row[2] * d[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16387; }
    { const char * tb_v16388 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16388; }
    { const char * tb_v16389 = "    double f = tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180);\n"; *(const char * *)tb_grow(v_lines) = tb_v16389; }
    { const char * tb_v16390 = "    if (tb_m3_test(m->bs, M, T, f, 1) == 0) return;   // вся сетка за камерой или вне окна\n"; *(const char * *)tb_grow(v_lines) = tb_v16390; }
    { const char * tb_v16391 = "    tb_mdrawn++;\n"; *(const char * *)tb_grow(v_lines) = tb_v16391; }
    { const char * tb_v16392 = "    for (long long c = 0; c < m->nch; c++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16392; }
    { const char * tb_v16393 = "        if (m->nch > 1 && tb_m3_test(m->chs + 4 * c, M, T, f, 1) == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16393; }
    { const char * tb_v16394 = "        for (long long t = m->chr[2 * c]; t < m->chr[2 * c] + m->chr[2 * c + 1]; t++) tb_lj_add(r, t, cull);\n"; *(const char * *)tb_grow(v_lines) = tb_v16394; }
    { const char * tb_v16395 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16395; }
