    { const char * tb_v16397 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v16397; }
    { const char * tb_v16398 = "// ---- карта теней: все сетки сцены глазами солнца (квадрат вокруг камеры), ближайшая глубина в каждой точке ----\n"; *(const char * *)tb_grow(v_lines) = tb_v16398; }
    { const char * tb_v16399 = "static void tb_sm_build(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16399; }
    { const char * tb_v16400 = "    long long N = TB_SM_N;\n"; *(const char * *)tb_grow(v_lines) = tb_v16400; }
    { const char * tb_v16401 = "    if (!tb_sm) tb_sm = (uint32_t *)malloc(sizeof(uint32_t) * (size_t)(N * N));\n"; *(const char * *)tb_grow(v_lines) = tb_v16401; }
    { const char * tb_v16402 = "    for (long long i = 0; i < N * N; i++) tb_sm[i] = 65535;\n"; *(const char * *)tb_grow(v_lines) = tb_v16402; }
    { const char * tb_v16403 = "    // оси: F — от солнца, R и U поперёк; центр — перед камерой, по сетке точек карты (тени не дрожат при движении)\n"; *(const char * *)tb_grow(v_lines) = tb_v16403; }
    { const char * tb_v16404 = "    for (int k = 0; k < 3; k++) tb_smF[k] = -tb_lt[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16404; }
    { const char * tb_v16405 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16405; }
    { const char * tb_v16406 = "    if (fabs(tb_smF[1]) > 0.99) { up[1] = 0; up[2] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16406; }
    { const char * tb_v16407 = "    double *F = tb_smF, *R = tb_smR, *U = tb_smU;\n"; *(const char * *)tb_grow(v_lines) = tb_v16407; }
    { const char * tb_v16408 = "    R[0] = up[1] * F[2] - up[2] * F[1]; R[1] = up[2] * F[0] - up[0] * F[2]; R[2] = up[0] * F[1] - up[1] * F[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v16408; }
    { const char * tb_v16409 = "    double l = sqrt(R[0] * R[0] + R[1] * R[1] + R[2] * R[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16409; }
