    { const char * tb_v16847 = "// углы сетки по порядку треугольников: место 3, нормаль 3, цвет 4, (u, v) 2, касательная 3 (куда растёт u), 1 пусто,\n"; *(const char * *)tb_grow(v_lines) = tb_v16847; }
    { const char * tb_v16848 = "// 4 кости и 4 веса (сумма не больше 1, остаток — на месте) — 24 числа\n"; *(const char * *)tb_grow(v_lines) = tb_v16848; }
    { const char * tb_v16849 = "enum { TB_SHV = 24 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16849; }
