    { const char * tb_v17258 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17258; }
    { const char * tb_v17259 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v17259; }
    { const char * tb_v17260 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17260; }
    { const char * tb_v17261 = "    for (int p = 0; p < TB_PADS; p++) tb_pads[p].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17261; }
    { const char * tb_v17262 = "    if (!cls) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v17262; }
    { const char * tb_v17263 = "    id all = TB_MSG(id, cls, \"controllers\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17263; }
    { const char * tb_v17264 = "    unsigned long n = all ? TB_MSG(unsigned long, all, \"count\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17264; }
    { const char * tb_v17265 = "    for (unsigned long i = 0; i < n && i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17265; }
    { const char * tb_v17266 = "        id c = TB_MSG1(id, all, \"objectAtIndex:\", unsigned long, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v17266; }
    { const char * tb_v17267 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17267; }
    { const char * tb_v17268 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v17268; }
