    { const char * tb_v17270 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17270; }
    { const char * tb_v17271 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v17271; }
    { const char * tb_v17272 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v17272; }
    { const char * tb_v17273 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17273; }
    { const char * tb_v17274 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v17274; }
