    { const char * tb_v17276 = "            id el = TB_MSG(id, g, bn[k]);\n"; *(const char * *)tb_grow(v_lines) = tb_v17276; }
    { const char * tb_v17277 = "            p->b[k] = el ? (int)TB_MSG(BOOL, el, \"isPressed\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17277; }
