    { const char * tb_v17281 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17281; }
    { const char * tb_v17282 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17282; }
    { const char * tb_v17283 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17283; }
    { const char * tb_v17284 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17284; }
    { const char * tb_v17285 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17285; }
    { const char * tb_v17286 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v17286; }
    { const char * tb_v17287 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17287; }
    { const char * tb_v17288 = "        p->a[TB_PA_RY] = -TB_MSG(float, TB_MSG(id, rs, \"yAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17288; }
    { const char * tb_v17289 = "        p->a[TB_PA_L2] = TB_MSG(float, TB_MSG(id, g, \"leftTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17289; }
    { const char * tb_v17290 = "        p->a[TB_PA_R2] = TB_MSG(float, TB_MSG(id, g, \"rightTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17290; }
    { const char * tb_v17291 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17291; }
    { const char * tb_v17292 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17292; }
    { const char * tb_v17293 = "#elif defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v17293; }
    { const char * tb_v17294 = "typedef struct { unsigned short buttons; unsigned char lt, rt; short lx, ly, rx, ry; } tb_xpad;\n"; *(const char * *)tb_grow(v_lines) = tb_v17294; }
    { const char * tb_v17295 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v17295; }
    { const char * tb_v17296 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17296; }
    { const char * tb_v17297 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17297; }
    { const char * tb_v17298 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17298; }
    { const char * tb_v17299 = "    if (!tried) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17299; }
    { const char * tb_v17300 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17300; }
    { const char * tb_v17301 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17301; }
    { const char * tb_v17302 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17302; }
    { const char * tb_v17303 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17303; }
    { const char * tb_v17304 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17304; }
    { const char * tb_v17305 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17305; }
    { const char * tb_v17306 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v17306; }
    { const char * tb_v17307 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v17307; }
    { const char * tb_v17308 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17308; }
    { const char * tb_v17309 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v17309; }
    { const char * tb_v17310 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v17310; }
    { const char * tb_v17311 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v17311; }
    { const char * tb_v17312 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17312; }
    { const char * tb_v17313 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v17313; }
    { const char * tb_v17314 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17314; }
    { const char * tb_v17315 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17315; }
    { const char * tb_v17316 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17316; }
