    { const char * tb_v17437 = "    if (tb_menu_n >= TB_MENU_MAX) tb_crash(line, \"menu_add: больше 256 пунктов меню не бывает\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17437; }
