    { const char * tb_v17441 = "    memcpy(top, path, tl); top[tl] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17441; }
    { const char * tb_v17442 = "    // клавиши: \"cmd+shift+s\" — cmd (Command на Mac, Ctrl на Windows), shift, alt, ctrl и одна клавиша в конце\n"; *(const char * *)tb_grow(v_lines) = tb_v17442; }
    { const char * tb_v17443 = "    int mods = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17443; }
