    { const char * tb_v17449 = "        if (n == 3 && strncmp(p, \"cmd\", 3) == 0) mods |= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17449; }
    { const char * tb_v17450 = "        else if (n == 5 && strncmp(p, \"shift\", 5) == 0) mods |= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17450; }
