    { const char * tb_v17453 = "        else { if (n >= sizeof key) n = sizeof key - 1; memcpy(key, p, n); key[n] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17453; }
    { const char * tb_v17454 = "        if (!e) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v17454; }
