    { const char * tb_v17477 = "// text_keys(): команды системы с прошлого раза через пробел (\"moveWordLeft: deleteBackward:\")\n"; *(const char * *)tb_grow(v_lines) = tb_v17477; }
    { const char * tb_v17478 = "TB_API const char *tb_text_keys(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17478; }
