    { const char * tb_v17486 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v17486; }
    { const char * tb_v17487 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v17487; }
    { const char * tb_v17488 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v17488; }
    { const char * tb_v17489 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v17489; }
    { const char * tb_v17490 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v17490; }
    { const char * tb_v17491 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v17491; }
    { const char * tb_v17492 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v17492; }
    { const char * tb_v17493 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v17493; }
    { const char * tb_v17494 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v17494; }
    { const char * tb_v17495 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v17495; }
    { const char * tb_v17496 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v17496; }
    { const char * tb_v17497 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v17497; }
    { const char * tb_v17498 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v17498; }
    { const char * tb_v17499 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v17499; }
    { const char * tb_v17500 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v17500; }
    { const char * tb_v17501 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v17501; }
    { const char * tb_v17502 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v17502; }
    { const char * tb_v17503 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v17503; }
    { const char * tb_v17504 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v17504; }
    { const char * tb_v17505 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v17505; }
    { const char * tb_v17506 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v17506; }
    { const char * tb_v17507 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v17507; }
    { const char * tb_v17508 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v17508; }
    { const char * tb_v17509 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v17509; }
    { const char * tb_v17510 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v17510; }
    { const char * tb_v17511 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v17511; }
    { const char * tb_v17512 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v17512; }
    { const char * tb_v17513 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v17513; }
    { const char * tb_v17514 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v17514; }
    { const char * tb_v17515 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v17515; }
    { const char * tb_v17516 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v17516; }
    { const char * tb_v17517 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v17517; }
    { const char * tb_v17518 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v17518; }
    { const char * tb_v17519 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v17519; }
    { const char * tb_v17520 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v17520; }
    { const char * tb_v17521 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17521; }
    { const char * tb_v17522 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17522; }
    { const char * tb_v17523 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v17523; }
    { const char * tb_v17524 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v17524; }
    { const char * tb_v17525 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17525; }
    { const char * tb_v17526 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17526; }
    { const char * tb_v17527 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17527; }
    { const char * tb_v17528 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v17528; }
    { const char * tb_v17529 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v17529; }
    { const char * tb_v17530 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17530; }
    { const char * tb_v17531 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v17531; }
    { const char * tb_v17532 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17532; }
    { const char * tb_v17533 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v17533; }
    { const char * tb_v17534 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17534; }
    { const char * tb_v17535 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v17535; }
    { const char * tb_v17536 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v17536; }
    { const char * tb_v17537 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v17537; }
    { const char * tb_v17538 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v17538; }
    { const char * tb_v17539 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v17539; }
    { const char * tb_v17540 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v17540; }
    { const char * tb_v17541 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17541; }
    { const char * tb_v17542 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17542; }
    { const char * tb_v17543 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v17543; }
    { const char * tb_v17544 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v17544; }
    { const char * tb_v17545 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17545; }
    { const char * tb_v17546 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v17546; }
    { const char * tb_v17547 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17547; }
    { const char * tb_v17548 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17548; }
    { const char * tb_v17549 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v17549; }
    { const char * tb_v17550 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17550; }
    { const char * tb_v17551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17551; }
    { const char * tb_v17552 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v17552; }
    { const char * tb_v17553 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17553; }
    { const char * tb_v17554 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v17554; }
    { const char * tb_v17555 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v17555; }
    { const char * tb_v17556 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17556; }
    { const char * tb_v17557 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17557; }
    { const char * tb_v17558 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v17558; }
    { const char * tb_v17559 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v17559; }
    { const char * tb_v17560 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17560; }
    { const char * tb_v17561 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v17561; }
    { const char * tb_v17562 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v17562; }
    { const char * tb_v17563 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v17563; }
    { const char * tb_v17564 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v17564; }
    { const char * tb_v17565 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v17565; }
    { const char * tb_v17566 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v17566; }
    { const char * tb_v17567 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17567; }
    { const char * tb_v17568 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17568; }
    { const char * tb_v17569 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v17569; }
    { const char * tb_v17570 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v17570; }
    { const char * tb_v17571 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v17571; }
    { const char * tb_v17572 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v17572; }
    { const char * tb_v17573 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v17573; }
    { const char * tb_v17574 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v17574; }
    { const char * tb_v17575 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v17575; }
    { const char * tb_v17576 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17576; }
    { const char * tb_v17577 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17577; }
    { const char * tb_v17578 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v17578; }
    { const char * tb_v17579 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v17579; }
    { const char * tb_v17580 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v17580; }
    { const char * tb_v17581 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17581; }
    { const char * tb_v17582 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17582; }
    { const char * tb_v17583 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17583; }
    { const char * tb_v17584 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v17584; }
    { const char * tb_v17585 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17585; }
    { const char * tb_v17586 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v17586; }
    { const char * tb_v17587 = "static void tb_snd_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17587; }
    { const char * tb_v17588 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v17588; }
    { const char * tb_v17589 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v17589; }
    { const char * tb_v17590 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17590; }
    { const char * tb_v17591 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v17591; }
    { const char * tb_v17592 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v17592; }
    { const char * tb_v17593 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v17593; }
    { const char * tb_v17594 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17594; }
    { const char * tb_v17595 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17595; }
    { const char * tb_v17596 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17596; }
    { const char * tb_v17597 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v17597; }
    { const char * tb_v17598 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17598; }
    { const char * tb_v17599 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17599; }
    { const char * tb_v17600 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17600; }
