    { const char * tb_v17930 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17930; }
    { const char * tb_v17931 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v17931; }
    { const char * tb_v17932 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17932; }
