    { const char * tb_v17937 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v17937; }
    { const char * tb_v17938 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17938; }
